// Üretilen dosya: tool/ozgun/uret.py. Sinema ve TV · Görsel efekt, animasyon teknikleri ve sinema teknolojisi (orta).
const ozCinema12Orta = <(String, String, List<String>, String)>[
  ('Belçikalı fizikçi Joseph Plateau\'nun 1832\'de geliştirdiği, dönen bir diskteki çizimlere ayna karşısında yarıklardan bakılarak hareket yanılsaması elde edilen optik oyuncağa ne ad verilir?', 'Fenakistoskop', ['Tavmatrop', 'Mutoskop', 'Kinetoskop'], 'Fenakistoskopta disk dönerken yarıklardan aynadaki görüntüye bakılır ve ardışık çizimler akıcı hareket olarak algılanır. Plateau\'nun bu icadı animasyonun atalarındandır.'),
  ('Bir yüzünde kuş, öbür yüzünde kafes çizili bir kartonun iki yanındaki iplerle hızla döndürülmesi, kuşun kafesin içinde görünmesini sağlar. Bu 1820\'lerde yaygınlaşan oyuncak hangisidir?', 'Tavmatrop', ['Fenakistoskop', 'Praksinoskop', 'Zoopraksiskop'], 'Tavmatrop, iki yüzdeki resmin göz tarafından birleştirilmesine dayanır. Hareket değil, görüntü birleşmesi sağlar; bu yüzden hareketli resmin değil \'kalıcılık\' ilkesinin basit bir gösterimidir.'),
  ('Hareketli görüntü algısını açıklarken \'gözün görüntüyü kısa süre tutması\' tek başına yeterli sayılmaz; 1912\'de Max Wertheimer\'in tanımladığı hangi olgu hareket yanılsamasını daha iyi açıklar?', 'Phi olgusu', ['Parallaks etkisi', 'Stroboskopik diyafram', 'Moiré etkisi'], 'Phi olgusunda iki ayrı yerde yanıp sönen ışık, beyin tarafından tek bir hareket eden ışık olarak algılanır. Sinemadaki ardışık karelerin hareket gibi görünmesi bu algısal mekanizmaya dayanır.'),
  ('Elle çevrilen kolla fotoğraf kartlarının hızla çevrilip tek kişinin bakabildiği, 1890\'larda eğlence salonlarında yaygın olan aygıt hangisidir?', 'Mutoskop', ['Kinetoskop', 'Sinematograf', 'Vitaskop'], 'Mutoskop, film şeridi yerine bir silindire dizili kartları çeviren bir aygıttı. Kinetoskoptan farkı elektriksiz çalışması ve şerit yerine kart kullanmasıdır.'),
  ('Projektörde filmin her karede durup bir sonrakine hızla ilerlemesini sağlayan, adını bir dinî simgeye benzeyen biçiminden alan dişli mekanizmanın adı nedir?', 'Malta haçı mekanizması', ['Fresnel prizma çarkı', 'Bayer süzgeç düzeni', 'Lamelli perde sistemi'], 'Malta haçı mekanizması sürekli dönen hareketi aralıklı harekete çevirir. Kare perdede dururken ışık geçer, film ilerlerken obtüratör ışığı keser.'),
  ('Rouben Mamoulian\'ın 1935 tarihli filmi, üç şeritli Technicolor ile çekilen ilk uzun metrajlı oyunlu film olarak anılır. Bu filmin adı nedir?', 'Becky Sharp', ['Mutiny on the Bounty', 'Anna Karenina', 'Cleopatra'], 'Becky Sharp (1935), Thackeray\'in \'Vanity Fair\' romanından uyarlanmış ve tam renk Technicolor ile çekilen ilk uzun metraj olmuştur.'),
  ('Technicolor baskılarında, üç renk için hazırlanan jelatinli matrislerin boyayı tek bir şeride aktararak kopyayı oluşturduğu yönteme ne ad verilir?', 'İmbibisyon baskısı', ['Optik baskı', 'Temas baskısı', 'Çift pozlama baskısı'], 'İmbibisyon baskısında matrisler boya emer ve boyayı alıcı şeride sırayla bastırır. Renkleri çok canlı ve solmaya dayanıklı baskılar verir, ama süreç yavaş ve pahalıdır.'),
  ('Kodak\'ın 1950\'de tanıttığı, tek şeritte üç renk katmanı taşıyan negatif film, Technicolor\'un üç şeritli kamerasını neden gereksiz kıldı?', 'Sıradan kameralarla renkli çekim yapılabildi', ['Daha fazla ışık gerektirmesi ve gece çekimine izin vermemesi', 'Ses kaydını doğrudan şeride işleyebilmesi', 'Siyah-beyaz çekimi tümüyle ortadan kaldırması'], 'Eastmancolor tek şeritlik bir negatiftir, bu yüzden büyük ve pahalı üç şeritli kamera gerekmedi. Maliyet düştü ve Technicolor kamera üretimini bıraktı.'),
  ('Leopold Godowsky Jr. ve Leopold Mannes\'in geliştirdiği, 1935\'te Kodak\'ın pazara sunduğu ve ev filmlerinde uzun yıllar kullanılan renkli film hangisidir?', 'Kodachrome', ['Eastmancolor', 'Agfacolor', 'Cinecolor'], 'Kodachrome, ters çevrilebilir (reversal) bir renkli filmdi. 16 mm ve 8 mm ev filmlerinde ve fotoğrafta uzun yıllar kullanıldı, canlı renkleriyle tanınırdı.'),
  ('Sessiz filmlerde \'tinting\' ve \'toning\' yöntemleri arasındaki temel fark nedir?', 'Tinting açık alanları, toning gümüşü renklendirir', ['Tinting yalnız sesi, toning yalnız görüntüyü boyar', 'Tinting elle, toning ise yalnızca makineyle yapılırdı', 'Tinting kopyayı boyar, toning ise negatifi parlatır'], 'Tinting\'de film tabanı ya da emülsiyon boyanır, aydınlık alanlar renkli görünür. Toning\'de ise karanlık gümüş parçacıkları kimyasalla renk değiştirir; ikisi birleştirilince çift renkli görüntü elde edilir.'),
  ('Lee de Forest\'ın 1920\'lerin başında geliştirdiği ve sesi filmin kenarına optik iz olarak kaydeden sistem hangisidir?', 'Phonofilm', ['Vitaphone', 'Kinetophone', 'Fantasound'], 'Phonofilm, ses-film üstü (sound-on-film) kaydın ilk uygulamalarındandır. Senkron sorununu ortadan kaldıran bu ilke, sonradan Movietone gibi sistemlerle yaygınlaştı.'),
  ('Plakla ses çalan Vitaphone yerine optik ses kaydı kullanan Movietone sistemi, sessiz sinemadan sese geçişte hangi pratik üstünlüğü sağladı?', 'Ses ile görüntü aynı şeritte olduğundan senkron bozulmuyordu', ['Ses kalitesi plaklardan her zaman çok daha yüksekti', 'Filmler sessiz salonlarda da değişiklik olmadan oynanıyordu', 'Ses kaydı kurguda hiç kesilemiyordu'], 'Movietone\'da ses film şeridinin kenarına yazıldığı için kurgu, kopyalama ve gösterimde ses görüntüden ayrılamazdı. Plak sistemi ise iğne atlaması ve senkron kayması riski taşıyordu.'),
  ('Edison\'un 1895\'te kinetoskopu ses için fonografla birleştirdiği ve izleyicinin kulaklıkla dinlediği sistemin adı nedir?', 'Kinetofon', ['Vitafon', 'Biyofon', 'Mutofon'], 'Kinetofon, kinetoskop görüntüsünü bir fonograf silindiriyle kayış üzerinden eşleştiriyordu. Ses ve görüntü tam uyumlu değildi ve tek kişilik izleme sınırlıydı.'),
  ('Sessiz dönemde projeksiyonlar yaklaşık 16-18 kare/sn hızla yapılırken, 1920\'lerin sonunda 24 kare/sn standart hâle geldi. Bu geçişin başlıca nedeni neydi?', 'Optik ses izi için daha hızlı film akışı gerekmesi', ['Perde parlaklığının artırılmasının istenmesi', 'Telif haklarının kare sayısına bağlanması', 'Kameraların çok daha ağır ve yavaş çalışması'], 'Film şeridinin kenarındaki ses izi, yeterli ses kalitesi için yeterince hızlı akmalıydı. 24 kare/sn, sesli film için pratik ve ekonomik bir standart olarak yerleşti.'),
  ('Edison ve Dickson\'ın 35 mm genişlikte ve her karenin kenarında dört delikle şeklini verdiği film standardı, sinema tarihinde hangi sonucu doğurdu?', 'Dünyada ortak film formatı olarak yerleşti', ['Aynı anda iki rakip ses sistemi doğdu', 'Filmlerin yalnız ABD\'de gösterilebilmesi', 'Renkli filmin kullanımının ertelenmesi'], 'Dickson\'ın 35 mm genişlik ve dört delikli kare standardı, Lumière dahil pek çok girişimci tarafından kabul edildi. Kamera ve projektör uyumu uluslararası film ticaretini mümkün kıldı.'),
  ('Conan Doyle\'un romanından uyarlanan ve stop-motion dinozorlarıyla 1925\'te seyirciyi şaşırtan, \'King Kong\'u hazırlayan animatörün öncü filmi hangisidir?', 'Kayıp Dünya', ['Gertie the Dinosaur', 'Aya Yolculuk', 'Nosferatu'], 'Willis O\'Brien, \'The Lost World\' (1925) filminde stop-motion dinozorları canlı oyuncularla birleştirdi. Bu deneyim, sekiz yıl sonra \'King Kong\' (1933) için temel oldu.'),
  ('Spielberg\'in \'Jurassic Park\' (1993) filminde animatörlerin, bilgisayara dinozor hareketi aktarmak için kullandığı, Phil Tippett stüdyosunun geliştirdiği algılayıcılı dinozor iskeletinin adı nedir?', 'Dinosaur Input Device', ['Motion Control Rig', 'Digital Armature Console', 'Creature Capture Suit'], 'Stop-motion animatörleri bilgisayar ortamına yabancı olduğu için Tippett Studio, kolayca tutulup oynatılan sensörlü bir dinozor iskeleti yaptı. Bu cihaz, animatör alışkanlığını dijital animasyona taşıdı.'),
  ('Laika\'nın \'Coraline\' (2009) ve \'ParaNorman\' (2012) filmlerinde kuklaların yüz değişimleri için kullanılan, hızlı prototipleme yöntemi hangisidir?', '3B yazıcıyla basılmış yüz parçaları', ['Elle oyulmuş ahşap yüz maskeleri', 'Kalıplanmış metal kafa modelleri', 'Bilgisayar çizimi saydam yüz katmanları'], 'Laika, kuklaların yüz ifadelerini bilgisayarda tasarlayıp 3B yazıcıyla basarak binlerce yüz varyasyonu üretti. Böylece animatörler daha ince ve tutarlı ifadeler elde etti.'),
  ('Rankin/Bass\'in \'Rudolph the Red-Nosed Reindeer\' (1964) gibi televizyon özelliklerinde kullandığı, Japonya\'daki bir stüdyoda yapılan stop-motion kukla süreci hangisidir?', 'Animagic', ['Pixilation', 'Claymation', 'Fantasound'], 'Rankin/Bass\'in \'Animagic\' adlı süreci, kuklaların Japonya\'da MOM Productions tarafından hareketlendirilmesine dayanıyordu. Yılbaşı özel yapımlarıyla televizyon tarihine geçti.'),
  ('Stop-motion çekimde bir karakterin kuklasının ayakları sete sabitlenir ki kare kare hareket sırasında kayıp devrilmesin. Bu sabitleme düzeneğine ne ad verilir?', 'Tie-down', ['Frame-hold', 'Loop-lock', 'Pin-clip'], 'Tie-down düzeneğinde kuklanın ayağındaki delikten sete vida geçirilir. Böylece kukla ağırlık merkezi bozulduğunda bile yerinde kalır ve her karede aynı konumu korur.'),
  ('Bir stop-motion yönetmeni 10 saniyelik bir planı 24 kare/sn hızda \'ikişerli\' çekiyor. Bu plan için kaç ayrı poz hazırlaması gerekir?', '120', ['240', '60', '480'], '10 sn x 24 kare = 240 kare gerekir. İkişerli çekimde her poz iki kare süre kaldığı için 240 / 2 = 120 poz yapılır.'),
  ('Tim Burton\'un 2012 yapımı \'Frankenweenie\' filmini, o dönemdeki diğer stop-motion filmlerinden ayıran görsel özelliği nedir?', 'Siyah-beyaz çekilmiş olması', ['Tamamen kâğıttan kuklalarla yapılması', 'Üç boyutlu stereoskopik çekimle başlaması', 'Hiç ses içermemesi'], 'Frankenweenie, hem kısa filmin hem de uzun metrajın siyah-beyaz estetiğini koruyarak klasik korku filmlerine gönderme yapar. Bu, stop-motion\'da renksiz çekimin ender bir örneğidir.'),
  ('Guillermo del Toro\'nun stop-motion tekniğiyle yaptığı \'Pinokyo\' (2022) hangi Oscar\'ı kazanmıştır?', 'En İyi Animasyon Filmi', ['En İyi Görsel Efekt', 'En İyi Özgün Müzik', 'En İyi Kurgu'], 'Del Toro\'nun \'Pinokyo\'su, Mark Gustafson\'la birlikte yönetilen bir stop-motion filmi olarak En İyi Animasyon Filmi Oscar\'ını kazandı.'),
  ('Charlie Kaufman ve Duke Johnson\'ın \'Anomalisa\' (2015) filmi stop-motion\'u hangi açıdan farklı kullanır?', 'Yetişkinlere yönelik ve baskı yüzlü kuklalarla', ['Sessiz ve tek renkli ekranla', 'Çocuk tiyatrosu mekânında canlı çekimle', 'Yalnız kâğıt kesme animasyonuyla'], 'Anomalisa, yetişkinlere yönelik gerçekçi bir dram olarak stop-motion kuklalarla çekilmiştir. Kuklaların yüzleri 3B baskıyla üretilmiştir.'),
  ('Bir animatör, stop-motion\'da çok sayıda ve küçük hareketle yürüyüş döngüsünü tamamlıyor. Hangisi, stop-motion\'un çizgi animasyona kıyasla sağladığı doğal avantajdır?', 'Gerçek ışık ve gerçek dokularla çekim', ['Karakteri sonsuz kez çoğaltabilme olanağı', 'Sesin görüntüden bağımsız kaydedilebilmesi', 'Perspektifin otomatik olarak düzeltilmesi'], 'Stop-motion\'da nesneler fiziksel olduğu için gerçek ışık, gölge ve doku kameraya doğrudan yansır. Çizgi animasyonda bunlar çizimle yaratılmak zorundadır.'),
  ('Bir stüdyo, kuklaların yüzü için binlerce hazır parçadan oluşan bir arşiv kullanıyor ve her karede uygun parçayı yerine takıyor. Bu yönteme genel olarak ne denir?', 'Değiştirmeli animasyon', ['Boyama animasyonu', 'Rotoskoplu çekim', 'Kesme animasyonu'], 'Değiştirmeli animasyonda kuklanın bir bölümü (yüz, ağız, kol) her karede farklı bir hazır parçayla değiştirilir. Böylece dudak eşleştirmesi ve ifade değişimi tekrarlanabilir hâle gelir.'),
  ('Disney\'in \'101 Dalmaçyalı\' (1961) filminde çizimlerin saydam asetata aktarılmasında hangi teknik, el emeğini azaltmak için ilk kez geniş çapta kullanıldı?', 'Fotokopi tekniği', ['Çift pozlama', 'Rotoskop', 'Mat painting'], 'Ub Iwerks\'in adapte ettiği kserografi, animatörün kurşun kalem çizimlerini doğrudan asetata aktardı. Böylece mürekkeplemeyi elle yapan ekibin yükü azaldı ve çizgi kalitesi doğal çizgi hâlini korudu.'),
  ('Disney\'in \'Mulan\' (1998) filmindeki Hun ordusunun koşusunu ölçekleyen yazılım, hangi sorunu çözdü?', 'Binlerce askerin bilgisayarla çoğaltılması', ['Seslendirmenin dudak hareketine uydurulması', 'Kamera rotasının otomatik belirlenmesi', 'Arka plan resimlerinin otomatik boyanması'], 'Mulan\'da \'Attila\' adlı kalabalık yazılımı, çizilmiş askerlerin çoğaltılıp bireysel hareket varyasyonu kazanmasını sağladı. Böylece binlerce figür el çizimiyle tek tek yapılmadan perdeye taşındı.'),
  ('Karakter hızla durduğunda saçları, kuyruğu ve giysisi birkaç kare daha hareket etmeye devam ediyor. Bu hangi animasyon ilkesidir?', 'Devam ve örtüşen hareket', ['Yavaş giriş ve yavaş çıkış', 'Sahneleme', 'Çekicilik'], 'Gövde durduğunda uzantılar ağırlık ve esneklikleri nedeniyle biraz daha hareket eder. Bu gecikmiş hareket, çizime fiziksel gerçekçilik kazandırır.'),
  ('Animatörün baştan sona kare kare sırayla çizdiği ve doğaçlama hissi taşıyan yönteme ne denir; önce uç pozlar çizilir ve ardından aralar doldurulursa hangisi uygulanmış olur?', 'Düz ileri; ikincisi poz-poz', ['Poz-poz; ikincisi düz ileri', 'Yavaş giriş; ikincisi hızlı çıkış', 'Kesme animasyon; ikincisi cam animasyon'], 'Düz ileri yöntemde animatör hareketin başından sonuna her kareyi sırayla çizer, spontane akış sağlar. Poz-poz yönteminde önce anahtar pozlar çizilir; zamanlama ve kontrol daha çok sağlanır.'),
  ('Bir karakter koşarken sakalının sallanması ya da yürürken saçını düzeltmesi gibi ana eylemi destekleyen küçük hareketler animasyonun hangi ilkesine girer?', 'İkincil eylem', ['Sahneleme', 'Zamanlama', 'Sağlam çizim'], 'İkincil eylem, ana hareketi zenginleştiren ve karakterin kişiliğini ya da ruh hâlini destekleyen küçük hareketlerdir. Ana eylemin dikkatini bozmayacak şekilde kullanılmalıdır.'),
  ('Çok hızlı bir sallanma anında karakterin kolunu birkaç kare boyunca bulanık, uzamış ve çok sayıda parmakla çizen animatör hangi tekniği kullanıyor?', 'Smear kareleri', ['Çift pozlama kareleri', 'Rotoskop kareleri', 'Cel kaydırma kareleri'], 'Smear karelerinde hızlı hareket, tek bir kare içinde uzatılmış ya da bulanık çizimle gösterilir. Bu, hareket bulanıklığının çizim karşılığı olarak görülür.'),
  ('Animasyonda dudak eşleştirmesinde, ünlü ve ünsüz seslere karşılık gelen ağız şekillerine genel olarak ne ad verilir?', 'Görsel sesbirimler', ['Anahtar pozlar', 'Kontur çizgileri', 'Zaman kodları'], 'Aynı ağız şekli birden fazla sese karşılık gelebildiği için sesbirimlere göre değil görsel sesbirimlere göre ağız şekilleri hazırlanır. Bu, dudak eşleştirmeyi pratikleştirir.'),
  ('Bir animasyonda hareket yalnız yüz kareden oluşan bir sahnede her çizimin kaç kare süreyle gösterileceğini, ses ve müzik işaretleriyle birlikte gösteren çizelgeye ne denir?', 'Çekim cetveli', ['Model sayfası', 'Hikâye panosu', 'Çizim ağacı'], 'Çekim cetveli, her kare için hangi çizimin, hangi arka planın ve hangi ses izinin kullanılacağını sütunlar halinde gösterir. Kamera ve animatör arasındaki iletişimi sağlar.'),
  ('Bir animasyon karakterinin gövdesinin duruşunu en baştan çizgi olarak gösteren ve hareketin ana yönünü belirleyen kıvrımlı çizgiye ne ad verilir?', 'Hareket çizgisi', ['Ufuk çizgisi', 'Odak çizgisi', 'Konturlama'], 'Line of action, bir pozun akışını ve enerjisini tek bir akıcı eğriyle gösterir. Animatörler karakter duruşunu bu çizgi üzerine kurarak güçlü ve okunur pozlar elde eder.'),
  ('Karakterin ağırlık, hacim ve derinlik izlenimini doğru perspektif ve ışıkla verebilmek animasyonun hangi ilkesine girer?', 'Sağlam çizim', ['Çekicilik', 'Aşırılaştırma', 'Devam hareketi'], 'Sağlam çizim, figürlerin üç boyutlu form, ağırlık ve denge anlayışıyla çizilmesidir. Düz ve yassı görünümü engeller.'),
  ('Geleneksel animasyonda karakterlerin kadraj içindeki konumunu, kamera açısını ve sahnenin kompozisyonunu animasyondan önce belirleyen aşamaya ne ad verilir?', 'Yerleşim', ['Mürekkeplendirme aşaması, çizgilerin saydam levhaya aktarıldığı bölüm', 'Çekim cetveli hazırlığı, karelerin süresinin saptandığı bölüm', 'Renk sınaması, boyaların film üzerinde denendiği bölüm'], 'Layout bölümü, storyboard ile animasyon arasındaki köprüdür. Arka plan perspektifini, karakterin yerini ve kamera hareketini belirler; animatörler bu rehber üzerinde çalışır.'),
  ('Cel animasyonunda boyacıların renkleri levhanın ters yüzüne uygulamasının temel nedeni nedir?', 'Boyanın düz görünmesi ve çizginin bozulmaması', ['Işığın boyaya doğrudan vurup rengi solduracağı kaygısı', 'Kameranın yalnızca arka yüzü net çekebilmesi', 'Boyanın saydam levhaya yalnızca ters yüzde yapışabilmesi'], 'Karakterin kontur çizgisi ön yüzde kalırken boya arka yüzden sürülür. Böylece boya, çizginin üzerine taşmaz ve yüzey düz bir renk alanı gibi görünür.'),
  ('Pixar\'da Ralph Eggleston\'ın popülerleştirdiği \'renk senaryosu\' (color script) neyi planlar?', 'Filmin duygusal akışını sahne sahne renk paletiyle', ['Karakterlerin kıyafet rengini seslendirme sırasında', 'Ses efektlerinin hangi karede başlayacağını', 'Bilgisayarda render sürelerinin sıralamasını'], 'Color script, filmin duygu eğrisini küçük renkli panolarla gösterir. Böylece ışık ve renk, anlatıdaki gerilim ve rahatlama anlarını destekleyecek biçimde planlanır.'),
  ('Disney stüdyosunda animatörlerin çalışmalarının yönetmen ve kıdemli isimlere gösterilip eleştirildiği toplantılara geleneksel olarak hangi ad verilirdi?', 'Terleme odası', ['Çekim odası, kameranın bulunduğu bölüm', 'Eskiz salonu, ilk çizimlerin yapıldığı oda', 'Sessiz oda, ses kayıtlarının yapıldığı yer'], 'Sweatbox, gösterim odasının sıkıcı ve gergin havasından adını alan bir Disney deyimidir. Çalışmaların yönetmene, bazen Walt Disney\'e, sunulduğu eleştiri oturumlarını anlatır.'),
  ('Bilgisayar animasyonunda animatörün önce kaba anahtar pozları sert geçişlerle (araları doldurulmadan) kurması aşamasına ne ad verilir?', 'Pozlama aşaması', ['Kaplama aşaması', 'Işıklandırma aşaması', 'Hareketlendirme sonrası düzeltme'], 'Blocking aşamasında karakter ana pozlarda sabit kalır ve zamanlama saptanır. Bilgisayar araları doldurmadan önce hareketin iskeleti oluşturulur.'),
  ('Adobe Flash\'ın (Macromedia) vektör tabanlı çizim kullanmasının animasyon açısından başlıca üstünlüğü nedir?', 'Büyütünce netlik kaybetmemeleri', ['Her çizim kare kare ayrı filme çekilir', 'Seslendirmenin otomatik üretilmesi', 'Üç boyutlu dönmenin doğrudan yapılabilmesi'], 'Vektör çizimler matematiksel eğrilerle tanımlandığı için ölçek değişse bile netliklerini korur. Dosya boyutu küçük olduğundan Flash, internet animasyonları için çok uygundu.'),
  ('Richard Linklater\'ın \'Waking Life\' (2001) filminde canlı çekimin üzerine çizilerek elde edilen dalgalı, boyalı görünüm hangi yöntemle üretilmiştir?', 'Bilgisayar destekli rotoskop', ['Pikselasyon', 'Çift pozlama', 'Stop-motion'], 'Filmin görüntüleri önce canlı oyuncularla çekildi, sonra çok sayıda sanatçı bilgisayar yazılımıyla bu görüntülerin üzerine çizim yaptı. Bu, Fleischer\'in rotoskopunun dijital karşılığıdır.'),
  ('Animasyonda \'ikişerli çekim\' (on twos) ile \'birerli çekim\' (on ones) arasındaki fark nedir?', 'İkişerli çekimde her çizim iki kare görünür', ['İkişerli çekimde iki kamera kullanılır', 'Birerli çekim yalnız renkli filmde yapılır', 'İkişerli çekimde çizimler iki kat büyüktür'], '24 kare/sn\'de birerli çekim 24, ikişerli çekim 12 ayrı çizim gerektirir. Hızlı aksiyonda birerli, ağır hareketlerde ikişerli çekim tercih edilir.'),
  ('Rotoskopla çalışırken ışık masasına konan film karelerinin üzerinden karakter çizildiğinde, hareket neden gerçekçi görünür?', 'Hareket gerçek oyuncudan alındığı için', ['Animatör çizimleri rastgele sıralayabildiği için', 'Kare sayısı düşük tutulduğu için', 'Renkler otomatik düzeltildiği için'], 'Rotoskopta animatör gerçek hareketin her karesini izleyerek çizdiği için ağırlık ve zamanlama doğaldır. Ancak abartı özgürlüğü azaldığı için bazı animatörler katı bulur.'),
  ('\'Doğrudan film üzerine çizim\' tekniğinde çizim alanı hangi nedenle çok küçüktür ve sabır gerektirir?', 'Karenin yalnız birkaç milimetre olması', ['Şeridin renkli olması', 'Boyaların sıvı olması', 'Kameranın hareket ettirilmesi'], '35 mm film karesi yaklaşık 22 x 16 mm\'dir. Sanatçının saniyede 24 kareye çizim veya kazıma yapması çok emek ister.'),
  ('Bilgisayar animasyonunda ateş, duman, kıvılcım gibi birbirinden bağımsız çok sayıda küçük öğenin benzetimini mümkün kılan, William Reeves\'in tanıttığı yöntem nedir?', 'Parçacık sistemleri', ['Doku haritalama', 'Kemik iskelet düzeni', 'Tel kafes çizimi'], 'Parçacık sistemi, her parçacığın konum, hız ve ömrünü kurallara göre hesaplayarak ateş ve duman gibi bulanık olguları üretir. İlk olarak Genesis efektinde kullanılmıştır.'),
  ('\'Forrest Gump\' (1994) filminde Forrest\'ın eski devlet başkanlarıyla görüşmesi hangi tekniğe dayanır?', 'Arşiv görüntüsüne oyuncunun eklenmesi', ['Devlet başkanlarını canlandıran benzer oyuncuların çekilmesi', 'Yalnız ses taklidi ve fotoğraf kolajı', 'Her kareyi tek tek çizen rotoskop'], 'Tom Hanks, dijital olarak arşiv görüntülerine yerleştirilerek tarihî kişilerle aynı karede göründü. Dudak hareketleri ve kamera hareketi bilgisayarla uyumlandı.'),
  ('Hironobu Sakaguchi\'nin yönettiği \'Final Fantasy: The Spirits Within\' (2001) filmi hangi yönüyle tartışma yarattı?', 'Gerçekçi dijital insan yüzü denemesi', ['Yalnız siyah-beyaz çekilmesi', 'Stop-motion ve bilgisayarın karışımı olması', 'Tamamen sessiz olması'], 'Film, fotogerçekçi insan karakterleri bilgisayarda yaratmayı amaçladı. Gişede başarısız oldu ve \'tekinsiz vadi\' tartışmasını güçlendirdi.'),
  ('\'Titanik\' (1997) filminde geminin güvertesinde yürüyen kalabalık figürlerin bir bölümü hangi yöntemle yaratıldı?', 'Hareket yakalamalı dijital insanlarla', ['Karton kesmelerle', 'Stop-motion kuklalarla', 'Cam üzerine boyalı figürlerle'], 'Titanic\'te güverteyi gösteren geniş planlarda hareket yakalamayla oluşturulmuş dijital figürler kullanıldı. Bu yöntem kalabalık maliyetini düşürdü.'),
  ('\'Gollum\' karakterinin teni ışığı hafifçe içine alıp saçarak canlı görünmesi için \'Yüzüklerin Efendisi: İki Kule\'de kullanılan render yöntemi nedir?', 'Yüzey altı saçılımı', ['Ortam tıkanıklığı', 'Işın izleme ile yansıma', 'Tel kafes görüntüleme'], 'Derinin ışığı emip yüzey altında dağıtması gerçekçilik için gereklidir. Subsurface scattering, Gollum\'un ve sonraki dijital karakterlerin canlı görünümünü sağladı.'),
  ('Bilgisayar efektlerinde nesnelerin birbirine yakın yüzeylerde ışığı daha az alıp köşelerde hafif gölge oluşturmasını sağlayan ve \'Pearl Harbor\' (2001) ile yaygınlaşan teknik hangisidir?', 'Ortam tıkanıklığı', ['Hareket bulanıklığı', 'Parçacık sistemi', 'Doku haritalama'], 'Ambient occlusion, nesnelerin kapalı bölgelerinde ortam ışığının azalmasını simüle eder. Küçük hesaplama maliyetiyle gerçekçi gölge derinliği verir.'),
  ('1997\'de Pixar\'ın \'Geri\'s Game\' kısa filminde ilk kez kullanılan ve düzgün, kıvrımlı yüzeyleri az poligonla temsil edebilen modelleme yöntemi nedir?', 'Alt bölümleme yüzeyleri', ['Voksel modelleme', 'Parçacık tabanlı modelleme', 'Tel kafes modelleme'], 'Subdivision surfaces, kaba bir kafesi matematiksel olarak sonsuz inceltip pürüzsüz yüzey elde eder. Pixar bu yöntemi karakter derisi ve kıyafetlerde kullandı.'),
  ('Pixar\'ın \'Monsters, Inc.\' (2001) filminde Sulley\'nin tüylerinin gerçekçi görünmesini sağlayan ve ayrı bir yazılım gerektiren bilgisayar tekniği hangisidir?', 'Kıl ve tüy benzetimi', ['Su yüzeyi hesaplaması', 'Kalabalık simülasyonu', 'Ses yönlendirmesi'], 'Sulley\'nin milyonlarca kılı, hareket ve rüzgâr gibi kuvvetlere tepki veren özel bir yazılımla benzetildi. Bu çalışma, kıl benzetimini animasyon stüdyolarının ortak aracı yaptı.'),
  ('Bir sahnede ışığın bir nesnenin yüzeyine çarpıp başka nesnelere de renk taşıması hesaba katılıyor. Bu hesaplama hangi bilgisayar grafiği kavramıyla adlandırılır?', 'Global aydınlatma', ['Doku eşleme', 'Kare enterpolasyonu', 'Hareket yakalama'], 'Global aydınlatmada ışığın yansıması, kırılması ve diğer yüzeylere renk saçması hesaplanır. Bu, sahneyi daha doğal ve gerçekçi gösterir.'),
  ('Bir 3B model üzerinde sanatçının yüz ifadelerini önceden hazırlayıp karakter ağlarken gülümseme oranını kaydırıcıyla karıştırması hangi yöntemle mümkündür?', 'Karışım şekilleri', ['Kemik tabanlı iskelet', 'Parçacık sistemi', 'Fiziksel benzetim'], 'Blend shapes, yüzün farklı ifadelerini ayrı modeller olarak saklar ve aralarını ağırlıklarla karıştırır. Yüz animasyonunda sık kullanılır.'),
  ('Avatar (2009) filminde James Cameron\'a Pandora ormanını çekerken sahne içinde dolaşıp kamera açısını gerçek zamanlı izleme olanağı veren araç hangisidir?', 'Sanal kamera', ['Sabit tripod', 'Cam levha çekimi', 'Mat painting kamerası'], 'Sanal kamera sistemi, yönetmenin elindeki monitörde dijital dünyayı canlı göstererek gerçek bir kamera gibi hareket ettirmesini sağladı.'),
  ('\'Pi\'nin Yaşamı\' (Life of Pi, 2012) filminin Richard Parker adlı kaplanının büyük bölümü nasıl üretildi?', 'Bilgisayarda yaratılan dijital kaplanla', ['Tamamen gerçek kaplanla', 'Stop-motion kuklayla', 'Mekanik animatronikle'], 'Filmde gerçek kaplan yalnız birkaç sahnede kullanıldı. Çoğu sahnede dijital kaplan Rhythm & Hues tarafından hazırlanıp görüntülere eklendi.'),
  ('James Cameron, Stan Winston ve Scott Ross\'un 1993\'te birlikte kurduğu ve \'Titanik\'in efektlerinde rol alan görsel efekt şirketi hangisidir?', 'Digital Domain', ['Pixomondo', 'Framestore', 'Rhythm & Hues'], 'Digital Domain, Cameron, Winston ve Ross tarafından kurulmuş; Titanic, Apollo 13 ve Benjamin Button\'ın yüz efektleri gibi projelerde çalışmıştır.'),
  ('Nolan\'ın \'Başlangıç\' (Inception, 2010) ve \'Yıldızlararası\' (Interstellar, 2014) filmleriyle En İyi Görsel Efekt Oscar\'ını kazanan Londra merkezli şirket hangisidir?', 'Double Negative', ['Weta Digital', 'Digital Domain', 'Industrial Light & Magic'], 'Double Negative, 1998\'de kurulmuş Londra merkezli bir efekt şirketidir. Nolan filmlerinde ve Oscar kazanan başka yapımlarda çalışmıştır.'),
  ('Richard Edlund\'un ILM\'den ayrılarak 1983\'te kurduğu ve \'Hayalet Avcıları\'nın efektlerini yapan şirketin adı nedir?', 'Boss Film Studios', ['Dream Quest Images', 'Apogee', 'Entertainment Effects Group'], 'Boss Film Studios, \'Ghostbusters\' ve \'Zor Ölüm\' gibi filmlerde çalıştı. Edlund, ILM\'de \'Star Wars\' ve \'Indiana Jones\' efektlerinde rol almıştı.'),
  ('\'Blade Runner\' (1982) filminde araçların ve gelecekteki Los Angeles\'ın görünümünü tasarlayan, kendisini \'görsel fütürist\' diye tanımlayan sanatçı kimdir?', 'Syd Mead', ['H. R. Giger', 'Ron Cobb', 'Moebius'], 'Syd Mead, araba ve kent tasarımlarıyla Blade Runner\'a imza attı. Aynı sanatçı \'Tron\' ve \'Aliens\' gibi filmlerde de çalıştı.'),
  ('Kameraya yakın bir yere, aralarında ya da önünde küçük bir maketin yerleştirilip arka planda büyük bir yapı izlenimi veren kamera önü tekniğine ne denir?', 'Asılı minyatür', ['Cam üzerine mat painting', 'Kuklaların ters çekimi', 'Çift pozlama'], 'Küçük model, kameraya yakın durduğu için perspektifle büyük görünür. Bu yöntem maliyeti düşürür ve gerçek bir set kurma ihtiyacını azaltır.'),
  ('Peter Jackson\'ın \'Yüzüklerin Efendisi\' filmlerinde yapılan, kaleler ve kentlerin büyük ölçekli maketlerine verilen ad nedir?', 'Bigature', ['Dioramalar', 'Matrixler', 'Arma kafesler'], 'Weta Workshop, kaleleri ve kentleri çok büyük ölçekli modeller olarak inşa etti. \'Bigature\' sözcüğü \'büyük minyatür\' anlamında kullanıldı.'),
  ('Kubrick\'in \'2001: Bir Uzay Destanı\' (1968) filminin \'İnsanlığın Şafağı\' bölümündeki Afrika arka planları hangi yöntemle sağlandı?', 'Önden yansıtma', ['Arka projeksiyon', 'Mat painting', 'Üç boyutlu maket'], 'Önden yansıtmada projektör, yarı geçirgen aynayla kamera ekseninde hizalanır ve yansıtılan görüntü, ışığı geri yansıtan perdeyle oyuncuların arkasında parlar. Gölge oluşmaz.'),
  ('Önden yansıtma yönteminde oyuncuların üzerine arka plan görüntüsünün düşmemesi hangi malzemenin özelliği sayesindedir?', 'Işığı kaynağına geri yansıtan perde', ['Mat siyah kumaş', 'Aynalı cam levha', 'Saydam plastik levha'], 'Retro-yansıtıcı perde, ışığı geldiği yöne geri gönderir. Oyuncuların üstüne düşen zayıf ışık, perdeye göre çok karanlık kalır ve görünmez.'),
  ('Douglas Trumbull\'un \'2001\' filminin \'Yıldız Geçidi\' sekansında kullandığı, ışığı dar bir yarıktan geçirip kamerayı hareket ettirerek ışık çizgileri yaratan teknik hangisidir?', 'Slit-scan', ['Zoptik', 'Rotoskop', 'Bluescreen'], 'Slit-scan\'de uzun pozlamada film ışığı dar bir yarıktan alırken sanat çalışması hareket eder; böylece uzamış ışık çizgileri elde edilir. Yıldız Geçidi sekansının görüntüsü bu şekilde oluştu.'),
  ('Sahne tiyatrosunda 1860\'larda John Henry Pepper\'ın popülerleştirdiği, eğik cam levha yardımıyla sahnede hayalet izlenimi veren yönteme ne ad verilir?', 'Pepper\'ın hayaleti', ['Schüfftan süreci', 'Zoetrop etkisi', 'Aya Yolculuk hilesi'], 'Gizli bir oyuncu veya nesne cam levhaya yansıtılır ve izleyici yansımayı sahnenin içinde görür. Bu ilke, sinemadaki mat ve ayna hilelerinin atasıdır.'),
  ('Bir efekt ekibi, arka plan çekimini ayrı yapıp oyuncuyu stüdyoda çekerek ikisini birleştiriyor. Sonuçta oyuncunun kenarlarında ince bir ışık halesi görünüyorsa sorun büyük olasılıkla nedir?', 'Perdeden yansıyan renk sızıntısı', ['Film hızının düşük olması', 'Objektifin odak dışı kalması', 'Müziğin yanlış seçilmesi'], 'Mavi ya da yeşil perde, oyuncunun saç ve kenarlarına renk bırakabilir. Bu \'spill\' kompozisyon sırasında düzeltilmezse kenarlarda halo oluşur.'),
  ('Peter Ellenshaw\'ın çalıştığı Disney\'de \'Mary Poppins\' sahnesindeki penguenlerle dans eden Dick Van Dyke görüntüsü hangi bileşik yöntemle yapıldı?', 'Sodyum buharı işlemi', ['Rotoskop', 'Mavi perde', 'Arka projeksiyon'], 'Sodyum buharı işleminde sarı ışıkla aydınlatılan perde, özel bir prizmayla ayrılarak kusursuz bir maske çıkarır. Disney bu yöntemi mavi perde sızıntısından kaçınmak için kullandı.'),
  ('\'Maymunlar Gezegeni\' (1968) filmindeki maymun maskelerini ve makyajını yapan John Chambers, yarışma dalı olmamasına rağmen Akademi\'den ne aldı?', 'Özel onur Oscar\'ı', ['En İyi Kostüm ödülü', 'En İyi Yardımcı Oyuncu ödülü', 'Bilim ve Teknik ödülü'], 'O dönemde Oscar\'da makyaj dalı yoktu. Akademi, Chambers\'ın çalışmasını özel bir onur ödülüyle taçlandırdı.'),
  ('Protez makyajda oyuncunun yüz kalıbının alçı ya da alginat ile alınmasının amacı nedir?', 'Protez parçalarının yüze tam oturacak biçimde yapılması', ['Oyuncunun ses tonunu ölçmek', 'Kameranın odak noktasını belirlemek', 'Kostümün rengini seçmek'], 'Yaşam kalıbı (life cast), oyuncunun yüz hatlarını kopyalar. Bu kalıpla heykel yapılır ve protezler kişiye uygun biçimde dökülür.'),
  ('Karton ve plastik yerine hafif ve esnek köpük lateksin protez makyajda tercih edilme nedeni nedir?', 'Cilt gibi esneyip yüz ifadelerini bozmadan taşınabilmesi', ['Işığı tümüyle yansıtması', 'Kamerada otomatik renk vermesi', 'Çok ucuz olup kısa sürede erimesi'], 'Köpük lateks hafif ve yumuşaktır; oyuncunun yüz hareketine uyar. Bu özelliği, 1960\'lardan sonra protez makyajda yaygın kullanıma yol açtı.'),
  ('\'Alien\' (1979) filmindeki göğüs delen yaratık sahnesinde oyuncuların şaşkın tepkisinin gerçek olmasını sağlayan şey neydi?', 'Kan fışkırmasının çekimde oyunculara önceden söylenmemesi', ['Gerçek bir hayvanın kullanılması', 'Işıkların aniden kapatılması', 'Seslerin ağır çekimde kaydedilmesi'], 'Yönetmen Ridley Scott, kanın patlayacağını bazı oyunculara söylememişti. Şaşkın tepkiler filmde gerçek korku olarak yansıdı.'),
  ('Japon canavar filmlerinde Eiji Tsuburaya\'nın geliştirdiği, bir oyuncunun yaratık kostümü içinde maket kentin ortasında dolaşması yöntemine ne ad verilir?', 'Takım elbise animasyonu', ['Pikselasyon', 'Rotoskop', 'Kamera hilesi'], 'Suitmation, Godzilla gibi canavarları kostümlü oyuncularla canlandırır. Maket binalar küçük ölçeklerde yapılır ve ağır çekimle çekilir.'),
  ('Superman (1978) filminin \'Bir adamın uçabileceğine inanacaksınız\' sloganını destekleyen, projektör ve kameranın zum hareketini eşleştiren yöntem hangisidir?', 'Zoptik', ['Dykstraflex', 'Vistavision', 'Dynamation'], 'Zoptik, Zoran Perisic tarafından geliştirilen bir zum düzeneğidir. Arka projeksiyon görüntüsü ile kameranın zumunun eşzamanlı değişmesiyle oyuncunun kameraya yaklaşıp uzaklaşıyor gibi görünmesi sağlandı.'),
  ('Yapımcılar, yüksek hızlı bir otomobil kazası sahnesinde otomobilin dönüşünü gerçekçi göstermek için gerçek bir araç yerine neyi kullanabilir?', 'Devrilme mekanizmalı özel kazalı araç', ['Karton model', 'Arka projeksiyon filmi', 'Stop-motion maketi'], 'Stunt ekipleri, motorlu kanatlı ya da sıkıştırılmış havayla çalışan düzeneklerle araçları kontrollü biçimde devirir. Böylece sahne tehlikesiz olarak çekilir.'),
  ('Sette sis ya da bulut izlenimi yaratmak için kuru buz kullanıldığında sisin yere yakın çökmesinin nedeni nedir?', 'Soğuk gazın havadan daha ağır olması', ['Işığın sisi aşağıya çekmesi', 'Kamera lensinin gazı emmesi', 'Sıcak havanın sisi yukarı itmesi'], 'Kuru buzun oluşturduğu soğuk karbondioksit buharı çevre havasından daha yoğundur ve yere çöker. Bu özellik, mezarlık ve sabah sisi sahnelerinde kullanılır.'),
  ('Setteki bir silah efektinde \'kör fişek\' ile \'gerçek mermi\' arasındaki en önemli güvenlik farkı nedir?', 'Kör fişekte kurşun yoktur ama yine de ölümcül olabilir', ['Kör fişek tamamen zararsızdır', 'Gerçek mermi dumansızdır', 'Kör fişek yalnız kapalı alanda kullanılır'], 'Kör fişek barut ve tapa içerir; yakın mesafede ciddi yaralanma ve ölüme yol açabilir. Bu yüzden silah ustası, güvenlik uzmanı ve sıkı protokoller gerekir.'),
  ('Patlama efektlerinde benzin yerine propan kullanılmasının tercih edilme nedenlerinden biri nedir?', 'Alevin daha kontrollü ve temiz yanması', ['Çok daha pahalı olması', 'Alevin hiç ısı üretmemesi', 'Hiçbir zaman gaz çıkmaması'], 'Propan, yanma sürecinde daha öngörülebilir ve temiz bir alev verir. Benzin ise kontrolsüz parlama ve dumana neden olabilir.'),
  ('Mekanik efekt ekibi bir geminin sarsılma sahnesini hangi düzenekle çekebilir?', 'Hidrolik ya da kardan eklemli sarsma platformu', ['Işık değişimi', 'Ağır çekim', 'Çift pozlama'], 'Büyük set parçaları hidrolik ya da sarkaçlı platformlara yerleştirilir. Böylece oyuncular gerçek bir sarsıntı içinde oynar ve kamera da onlarla hareket eder.'),
  ('Bir kompozisyon sanatçısı, perdeden uzak kalan ışık sehpalarını ve perde dışı kısımları görüntüden çıkarmak için ham ve kaba bir maske çiziyor. Bu maskeye ne ad verilir?', 'Çöp maskesi', ['Alfa maskesi', 'Hareket maskesi', 'Gölge maskesi'], 'Garbage matte, kesin kenar çıkarmayı beklemeden gereksiz alanları hızla gizler. Böylece anahtarlama yalnız önemli bölgelere uygulanır.'),
  ('Bir sahnede oyuncunun üstünden kaldırılan tellerin ve ekipmanın silinebilmesi için içinde oyuncu bulunmayan boş arka planın çekilmesine ne denir?', 'Temiz plaka', ['Alfa kanalı', 'Yedek kare', 'Kontrast kartı'], 'Clean plate, aynı kamera hareketi ve ışıkla çekilmiş boş sahnedir. Efekt sanatçısı bunu kullanarak aksesuarı kolayca görüntüden çıkarır.'),
  ('Yeşil perdeye yapıştırılan küçük işaret noktalarının asıl amacı nedir?', 'Kamera hareketinin bilgisayarda yeniden hesaplanması', ['Perdenin rengini sabitlemek', 'Oyuncunun yerini belirlemek', 'Işık ölçmek'], 'İşaretler, kamera hareketini izleyen yazılıma sabit noktalar sağlar. Bilgisayar grafiği sahneye, kamera hareketine uyumlu şekilde yerleştirilebilir.'),
  ('Efekt çekimlerinde objektifin yarattığı bozulmayı sonradan kaldırmak ya da eklemek için sete getirilen referans nedir?', 'Kareli ızgara kartı', ['Gri kart', 'Altın yansıtıcı', 'Renk filtresi'], 'Izgara kartı, objektif bozulmasını ölçmeyi sağlar. Efekt sanatçıları görüntüyü düzeltip bilgisayar grafiğiyle uyumlu hale getirir.'),
  ('Efekt ekibinin, bilgisayar grafiği için sahnedeki ışık yönünü ve rengini kaydetmek amacıyla sette çektiği yansıtıcı küreye ne ad verilir?', 'Krom küre', ['Alfa küresi', 'Gölge topu', 'Prizma kartı'], 'Krom küre, çevredeki ışık kaynaklarını ve yansımaları kaydeder. Yüksek dinamik aralıklı (HDRI) bir görüntü elde edilerek dijital nesnelerin ışıklandırması gerçekle eşleşir.'),
  ('Bir yeşil perde çekiminde oyuncunun saçlarının çevresindeki ince tellerin doğal ve yarı saydam çıkması için hangi uygulama önemlidir?', 'Perdenin eşit aydınlatılması ve ince anahtar ayarı', ['Siyah-beyaz çekim', 'Perdenin parlak olması', 'Kamerayı sabit tutmamak'], 'Perde eşit aydınlanırsa anahtarlama yazılımı saç gibi ince ayrıntıları daha temiz ayırır. Eşitsiz aydınlatma halo ve gürültü yaratır.'),
  ('Optik ve eylemsiz (inertial) hareket yakalama sistemleri arasındaki başlıca fark nedir?', 'Optik sistem kamera ve işaretçi, eylemsiz sistem vücuttaki algılayıcılar kullanır', ['Optik sistem yalnız yüz için çalışır', 'Eylemsiz sistem çok sayıda kameraya bağlıdır', 'Optik sistem yalnız hayvanlar içindir'], 'Optik yöntemde reflektif işaretçiler kameralarca izlenir; eylemsiz yöntemde giysideki ivmeölçerler hareketi kaydeder. İkincisi stüdyo dışında daha esnek çalışır.'),
  ('James Cameron\'ın \'Avatar\'ında oyuncuların başına takılan ve yüzlerine yönelen küçük kamera düzeneği ne işe yarar?', 'Yüz ifadelerinin ayrıntılı kaydedilmesi', ['Işık ölçümü', 'Sesin kaydedilmesi', 'Kamera sabitlemesi'], 'Kafaya takılı kamera, mimikleri ve göz hareketlerini kaydeder. Veri, Na\'vi karakterlerinin yüz animasyonuna aktarılır.'),
  ('\'Rogue One\' (2016) filminde Peter Cushing\'in canlandırdığı Grand Moff Tarkin karakteri nasıl yeniden yaratıldı?', 'Başka bir oyuncunun hareketine dijital yüz giydirilerek', ['Eski film görüntüleri kesilerek', 'Yalnız makyajla', 'Maket kuklayla'], 'Cushing 1994\'te ölmüştü. Guy Henry\'nin oyunculuğu üzerine Cushing\'in yüzü bilgisayarla yeniden oluşturuldu.'),
  ('\'Benjamin Button\'ın Tuhaf Hikâyesi\' (2008) filminde Brad Pitt\'in yaşlı hâli, yüzü hangi yöntemle elde edilmiş küçük bir bedene yerleştirilerek oynatıldı?', 'Dijital olarak yaşlı yüzün başka bedene eklenmesiyle', ['Gerçek yaşlı makyajıyla', 'Stop-motion kuklayla', 'Hareketli maske çekimiyle'], 'Digital Domain, Pitt\'in yüzünü ölçüp yaşlı hâlini bilgisayarda yaptı. Dijital baş, farklı bedenlere eklenmiş ve Oscar\'lı efektin temelini oluşturmuştur.'),
  ('\'The Mandalorian\' (2019) dizisinde ILM\'nin kullandığı, dev LED duvarlarda gerçek zamanlı çizilen çevrelerden oluşan sisteme genel olarak ne ad verilir?', 'LED hacim', ['Arka projeksiyon duvarı', 'Yeşil perde stüdyosu', 'Cam üzerine boyalı sahne'], 'StageCraft\'ta oyunlar için kullanılan gerçek zamanlı motorla üretilen çevreler, LED duvarlarda gösterilir. Kamera hareket ettikçe perspektif de değişir.'),
  ('LED hacim sisteminde oyuncunun parlak zırhının doğal yansımalar göstermesi, yeşil perdeye kıyasla hangi üstünlüğü gösterir?', 'Çevre ışığı ve yansıması gerçek zamanlı oluşur', ['Zırh daha hafif olur', 'Kameralar daha ucuz olur', 'Seslendirme kolaylaşır'], 'LED duvarlar, hem arka plan hem de ışık kaynağı görevi görür. Yeşil perde ise parlak yüzeyde yeşil sızıntı bırakıp sonradan düzeltme gerektirir.'),
  ('LED hacim sisteminde kameranın baktığı alanın yüksek çözünürlükte, çevresinin ise düşük çözünürlükte çizilmesi neden yapılır?', 'Bilgisayar yükünü azaltıp paralaks etkisini korumak', ['Perdenin ömrünü uzatmak', 'Işık miktarını azaltmak', 'Ses kaydını kolaylaştırmak'], 'Kamera takip edildiği için yalnızca görüş alanı ayrıntılı çizilir. Bu yöntem hem donanımı rahatlatır hem de hareket eden kamera için doğal paralaks sağlar.'),
  ('Önceden görselleştirmenin çekim sonrası uygulaması olan, geçici bilgisayar grafiğini canlı görüntüye yerleştirip kurgunun yapılmasını sağlayan aşamaya ne denir?', 'Postviz', ['Previs', 'Tekniviz', 'Pitchviz'], 'Postviz, nihai efekt yapılmadan önce kaba bilgisayar görüntülerini kurguya katar. Böylece kurgucu ve yönetmen sahne akışını değerlendirebilir.'),
  ('\'Aslan Kral\' (2019) yapımında Jon Favreau\'nun ekibi, sanal ortamda yönetmenin gezip kamera yerleştirmesini nasıl sağladı?', 'Sanal gerçeklik gözlükleriyle bilgisayar setinde dolaşarak', ['Cam üzerine çizilmiş setle', 'Küçük maketlerle', 'Gerçek hayvanlarla'], 'Yönetmen ve görüntü yönetmeni, VR başlıklarla sanal savanda dolaşıp çekim yaptı. Bu süreç, canlı çekim alışkanlıklarını sanal ortama taşıdı.'),
  ('1970\'lerde anamorfik filmlerin oranı 2,35:1 yerine 2,39:1 olarak standartlaştırıldı. Bu değişikliğin başlıca nedeni neydi?', 'Yapıştırma izlerinin perdede görünmesini azaltmak', ['Perdeleri biraz daha büyük gösterebilmek', 'Renk sıcaklığını bir miktar yükseltmek', 'Sesi kareden tümüyle ayırabilmek'], 'Film kopyalarında kurgu yapıştırma izleri çerçeveye girerse görünürdü. Standart biraz daraltılarak bu izlerin görünmesi önlendi.'),
  ('Super 35 formatının sağladığı temel avantaj aşağıdakilerden hangisidir?', 'Ses izi alanını da görüntüye katması', ['Filmi inceltip kopya maliyetini sıfırlaması', 'Yalnız siyah-beyaz film kullanması', 'Sesi doğrudan şerit kenarına kazıması'], 'Super 35\'te negatif, ses izi alanı dahil tüm genişlikten yararlanır. Sonradan geniş ekrana göre kırpılabilir ya da optik olarak sıkıştırılır.'),
  ('\'The Hurt Locker\' (2008) gibi düşük bütçeli yapımlarda tercih edilen, optik ses şeridi alanını da görüntüye katan dar film formatı hangisidir?', 'Süper 16 mm', ['Standart 8 mm', '9,5 mm', '65 mm'], 'Süper 16, 16 mm filmde optik ses için ayrılan şerit alanını da görüntüye katar. Daha geniş kare ve düşük maliyet sağlar.'),
  ('Kodak\'ın 1932\'de Büyük Buhran sırasında tanıttığı ve 16 mm filmin iki kez çekilip ikiye bölünmesi esasına dayanan ev formatı hangisidir?', 'Standart (çift) 8 mm', ['Super 8 kartuş sistemi', 'Pathé Baby sistemi', 'Süper 16 mm sistemi'], 'Çift 8 mm, 16 mm şerit üzerinde iki geçişte çekilir, laboratuvarda ikiye bölünür. Ucuz olması nedeniyle ev filmlerinin yaygınlaşmasını sağladı.'),
  ('Letterbox yönteminin pan and scan\'e göre başlıca üstünlüğü nedir?', 'Kadrajın yatay genişliğini koruması', ['Daha yüksek çözünürlük sunması', 'Sesin kalitesini artırması', 'Renklerin daha canlı çıkması'], 'Letterbox, filmin tüm kadrajını korur; siyah bantlar üst ve altta kalır. Böylece yönetmenin kompozisyonu bozulmaz.'),
  ('Her kare için 4 delik yerine 3 delik kullanan 3-perf 35 mm sistem, film tüketiminde yaklaşık yüzde kaç tasarruf sağlar?', 'Yüzde 25', ['Yüzde 10 civarı', 'Yüzde 50 civarı', 'Yüzde 33 civarı'], '3/4 = 0,75 olduğu için film tüketimi dörtte bir azalır. Özellikle uzun televizyon dizilerinde bu tasarruf önemlidir.'),
  ('Hitchcock\'un \'Dial M for Murder\' (1954) filmiyle ilgili hangisi doğrudur?', '3D çekildi ama çoğu salonda düz oynadı', ['Yalnız radyo oyunu olarak yazıldı', 'Siyah-beyaz çekilip sonra renklendirildi', 'Tek mekânda geçmeyecek biçimde çekildi'], 'Film, 3D çekimle hazırlandı; fakat 3D akımının düşmesiyle çoğu salonda 2D gösterildi. Bu nedenle 3D sürümü uzun süre az görüldü.'),
  ('Aktif perdeli (shutter) 3D gözlüklerin çalışma ilkesi nedir?', 'Projektörle eşgüdümlü sırayla gözleri kapatmak', ['Renk filtresiyle görüntüyü ayırmak', 'Işığı kutuplayarak ayırmak', 'Işık miktarını iki katına çıkarmak'], 'Gözlükler, perdeyi kapatıp açarak sol ve sağ görüntüyü sırayla gösterir. Bu yöntem pil ve eşgüdüm gerektirir.'),
  ('Perdede nesnenin seyirciye doğru fırlıyormuş gibi görünmesi 3D\'de hangi paralaks durumuna denk gelir?', 'Negatif paralaks', ['Pozitif paralaks hâli', 'Sıfır paralaks hâli', 'Sonsuz paralaks hâli'], 'Negatif paralakste nesne perde düzleminin önünde algılanır. Pozitif paralakste perdenin arkasında, sıfır paralakste ise perde düzleminde görünür.'),
  ('Film emülsiyonunda ışığa duyarlı gümüş halojenür kristalleri büyüdükçe film stokunda hangi değişim görülür?', 'Duyarlılık artar, tane belirginleşir', ['Duyarlılık düşer, görüntü pürüzsüzleşir ve renk doygunluğu artar', 'Duyarlılık sabit kalır, yalnız kontrast ayarlanır', 'Duyarlılık artar, tane tamamen kaybolur ve çözünürlük yükselir'], 'Büyük kristaller daha çok ışık yakalar, yani film hızlanır. Ancak görüntüde tane daha görünür olur ve çözünürlük azalır.'),
  ('Kodak Vision3 serisindeki \'500T\' kodunda \'T\' harfi neyi gösterir?', 'Tungsten ışığa dengelenmiş olmasını', ['Tane boyutunun çok ince olduğunu ve gün ışığına göre ayarlandığını', 'Filmin geçici baskıya uygun olduğunu ve kısa ömürlü olduğunu', 'Filmin tek şeritli teknik ölçüsünü ve ses uyumluluğunu'], 'T, filmin 3200 K tungsten ışığa göre dengelendiğini gösterir. Gün ışığında kullanmak için \'D\' serisi veya filtre gerekir.'),
  ('Ters çevrilebilir (reversal) filmin negatif filmden başlıca farkı nedir?', 'Kamerada çekilen şeritte doğrudan pozitif görüntü oluşur', ['Kamerada çekilen şeritte yalnız görüntünün siyah-beyaz negatifi oluşur', 'Yalnız stüdyo ışığında çalışır ve film hızı çok düşüktür', 'Banyoda kimyasal yerine ısı kullanılır ve kopya gerektirmez'], 'Reversal film banyo sonrasında projeksiyona hazır pozitif görüntü verir. Bu yüzden Kodachrome ve Super 8 gibi ev filmlerinde yaygındı.'),
  ('Renkli negatif filmin turuncu renkli görünmesinin nedeni nedir?', 'Boyaların kusurunu dengeleyen bütünleşik maske', ['Filmin yaşlanırken sararması ve ışıktan etkilenmesi', 'Kamerada kullanılan turuncu filtrenin kalıcı olması', 'Işığı yansıtan emülsiyonun metal içermesi'], 'Turuncu maske, renk bileşenlerindeki istenmeyen soğurmayı telafi eder. Baskı sırasında renklerin doğru çıkmasını sağlar.'),
  ('Asetat tabanlı eski film şeritlerinin bozulurken sirke kokusu yaymasına ne ad verilir?', 'Sirke sendromu', ['Nitrat yanması', 'Gümüş kararması', 'Boya solması'], 'Asetat taban kimyasal olarak ayrışınca asetik asit açığa çıkar. Şerit büzülür, kırılgan olur ve bozulma başka şeritlere de yayılır.'),
  ('Bir yönetmen, filmin renklerini bilerek bozup canlı ve beklenmedik tonlar elde etmek için negatif filmi pozitif kimyasalda banyo ettiriyor. Bu yöntem nedir?', 'Çapraz işleme', ['Ağartma atlama', 'Yarı pozlama', 'Pull işleme'], 'Çapraz işlemde film, öngörülen kimyasal yerine başka bir sürece tabi tutulur. Sonuçta kontrast ve renk kayması oluşur.'),
  ('Laboratuvarda \'zamanlama\' (timing) uzmanının görevi nedir?', 'Planlar arasında renk ve yoğunluğu dengelemek', ['Kamera hızını ayarlamak ve film boyutunu belirlemek', 'Kurgu sırasını belirlemek ve çekimleri sıralamak', 'Sesin görüntüyle eşlenmesini sağlamak ve senkronu düzeltmek'], 'Timer, planlar arasında renk ve yoğunluk farklarını giderir. Böylece sahne bütünlüğü sağlanır.'),
  ('Negatif kesicilerin pamuk eldiven giymesinin nedeni nedir?', 'Yağın emülsiyona zarar vermesini önlemek', ['Filmin elektrik yüklenmesini artırmak', 'Işığın şeride sızmasını engellemek', 'Şerit kenarındaki delikleri korumak'], 'Yağ ve ter, film yüzeyinde kalıcı lekeler bırakır. Orijinal negatif tek ve yeri doldurulamaz olduğundan çok dikkatli işlenir.'),
  ('Filmde \'tane\' (grain) görünümünün 16 mm\'de 35 mm\'ye göre belirgin olmasının nedeni nedir?', 'Karenin küçük olup perdeye çok büyütülmesi', ['Emülsiyonun renkli olması ve ince şeritte kimyasal farklılık', 'Kameranın daha hızlı çalışması ve obtüratörün farklı olması', 'Şeridin yalnız siyah-beyaz olması ve gümüşün çok az olması'], 'Küçük kare perdeye daha fazla büyütülür; dolayısıyla tane de büyür. Bu yüzden 16 mm daha sert, dokulu görünür.'),
  ('Mitchell BNC gibi eski stüdyo kameralarının çalışma gürültüsü için kullanılan ses yalıtımlı kılıfa ne ad verilir?', 'Blimp', ['Matte box', 'Magazin', 'Gimbal'], 'Sesli sinema döneminde kameranın motor sesi mikrofonlara geçmesin diye kameralar ses yalıtımlı kılıf (blimp) içine konurdu. Daha sonra sessiz çalışan kameralar bu ihtiyacı azalttı.'),
  ('Kamera mekanizmasında filmin her karede kısa süre sabit kalmasını sağlayan ve çekme dişiyle birlikte çalışan parça hangisidir?', 'Kayıt piminin kareyi sabitlemesi', ['Malta haçının filmi gevşetmesi', 'Obtüratörün sürekli kapanması', 'Diyaframın film hızına bağlanması'], 'Çekme dişi şeridi bir kare ilerletir, ardından registration pin kareyi sabitleyerek pozlama sırasında hareket etmesini önler. Görüntü titremesi böylece azalır.'),
  ('Dönen aynalı obtüratör kullanan kameralarda operatör neden çekim yapılan görüntüyü neredeyse kesintisiz görebilir?', 'Ayna ışığı kareler arasında vizöre yollar', ['Işık aynı anda hem filme hem vizöre düşer ve görüntü ikiye ayrılır', 'Kamera hızı vizör için otomatik olarak düşürülür', 'Görüntü vizöre ayrı bir dijital ekrandan gelir ve gecikmelidir'], 'Obtüratör aynası film açık değilken ışığı vizöre gönderir. Yüksek hızlı dönüş nedeniyle göz titreme fark etmez.'),
  ('Sony HDW-F900 kamerasıyla çekilen ve ilk büyük ölçekli tamamen dijital çekimli film sayılan 2002 yapımı Yıldız Savaşları bölümü hangisidir?', 'Klonların Saldırısı', ['Gizli Tehlike bölümü', 'Sith\'in İntikamı bölümü', 'Yeni Umut bölümü'], 'George Lucas, \'Episode II: Attack of the Clones\' filmini 24 kare progresif yüksek çözünürlüklü dijital kamerayla çekti. Bu, büyük bütçeli sinemada dijital çekime geçişin simgesidir.'),
  ('Dijital kamera sensörlerinde sıklıkla kullanılan Bayer filtresinde yeşil piksellerin kırmızı ve maviden iki kat fazla olmasının nedeni nedir?', 'Gözün yeşile daha duyarlı olması', ['Yeşil ışığın daha ucuz üretilmesi', 'Sensörün yeşili daha zayıf algılaması', 'Yeşil perde çekimine uygun olması'], 'Bayer düzeni RGGB desenindedir. İnsan görmesi yeşil dalga boylarında daha ayrıntılı olduğundan çözünürlük için yeşil iki kat örneklenir.'),
  ('Dijital sinema kameralarının çoğunda Super 35 boyutuna yakın sensör kullanılmasının nedeni nedir?', 'Film dönemindeki derinlik ve objektif uyumu', ['Çok daha az ışık gerektirmesi ve gecenin gündüze dönüşmesi', 'Her koşulda çok daha ucuza gelmesi', 'Sesi doğrudan sensörde kaydedebilmesi'], 'Super 35 boyutu, film dönemi objektiflerini ve alan derinliği alışkanlıklarını korur. Bu yüzden görüntü yönetmenleri değişime kolay uyum sağlar.'),
  ('Sinema objektiflerinde f sayısı yerine T sayısının (T-stop) kullanılmasının nedeni nedir?', 'Gerçek ışık geçirgenliğini göstermesi', ['T sayısının her objektifte aynı olması ve değişmemesi', 'Diyaframın hiç değişmemesi ve sabit kalması', 'Odak uzaklığını doğrudan milimetre cinsinden vermesi'], 'f sayısı yalnız geometrik orandır. T sayısı, objektifteki ışık kaybını da hesaba katar; aynı T\'ye ayarlı objektifler aynı pozlamayı verir.'),
  ('Sinema kameralarında yaygın olan PL bağlantı tipindeki \'PL\' kısaltması neyi ifade eder?', 'Positive Lock', ['Panavision Lens', 'Primary Light', 'Plain Lens'], 'PL, ARRI\'nin geliştirdiği ve sinema dünyasında yaygınlaşan objektif bağlantı standardıdır. \'Positive Lock\' sağlam kilitlenmeyi anlatır.'),
  ('Kamera önüne takılan ve ışık sızmasını ya da lens parlamasını engelleyen, ayarlanabilir kanatlı aksesuar nedir?', 'Matte box', ['Gimbal', 'Magazin', 'Takip odağı'], 'Matte box, filtreleri tutar ve yan ışığı keserek lens parlamasını azaltır. Bayraklar da bu amaçla eklenir.'),
  ('Bir operatör kameradaki kare hızını 24\'ten 48\'e çıkarıp obtüratör açısını 180 derecede tutuyor. Pozlama süresi nasıl değişir?', 'Yarıya iner', ['İki katına çıkar', 'Aynı kalır', 'Dörtte bire düşer'], 'Süre = obtüratör açısı / (360 x kare hızı). Kare hızı iki katına çıkınca 1/48\'den 1/96 saniyeye iner; yani pozlama yarıya düşer.'),
  ('Stadyumlarda yüksek gerilimli kablolara asılı bir kameranın saha üzerinde dolaşmasını sağlayan sistemlerin genel adı nedir?', 'Kablo askılı kamera', ['Dolly ve ray', 'Hava tüneli kamerası', 'Jiroskop sehpası'], 'Kablo askılı kamera, kablo uzunluklarını bilgisayarla ayarlayarak üç boyutlu uzayda hareket eder. Spor yayınlarında ve konserlerde yaygındır.'),
  ('Kamerayı oyuncunun gövdesine sıkıca bağlayıp yüzüne bakar hâle getiren ve \'Requiem for a Dream\'de sıkça kullanılan çekim düzeneğine ne denir?', 'Snorricam', ['Steadicam', 'Technocrane', 'Gimbal baş'], 'Snorricam\'de kamera oyuncuyla birlikte hareket ettiği için oyuncunun yüzü sabit, arka plan ise sallanıyor görünür. Sersemlik ve bunalım duygusu verir.'),
  ('Hidrolik sıvılı tripod başlıklarının sinemada tercih edilmesinin nedeni nedir?', 'Pan ve tilt hareketlerini yumuşak ve kesintisiz kılmaları', ['Kameranın ağırlığını yarıya indirmeleri ve titreşimi tamamen yok etmeleri', 'Sesi doğrudan kayda eklemeleri ve çekim sırasında sessiz çalışmaları', 'Renk dengesini otomatik ayarlamaları ve ışığı filtrelemeleri'], 'Sıvı sönümlemeli başlıklar, hareketin başlangıcını ve sonunu yumuşatır. Böylece pan ve tilt akıcı olur.'),
  ('Aydınlatmada ışık kaynağının özneye göre boyutu büyüdükçe ışığın karakteri nasıl değişir?', 'Daha yumuşak ve gölgeleri daha belirsiz olur', ['Daha sert ve gölgeleri daha keskin olur', 'Daha mavi olur ve renk sıcaklığı yükselir', 'Daha az ışık verir ve yalnız gece çekiminde işe yarar'], 'Büyük kaynak, özneye farklı açılardan ışık verdiği için gölge kenarları yumuşar. Küçük kaynak ise sert ve keskin gölge yapar.'),
  ('Işığın bir kısmını bloke eden siyah kumaş ya da panele ne denir, ışığın yoğunluğunu rengini değiştirmeden azaltan metal ya da ipek ağa ise ne denir?', 'Bayrak; scrim', ['Bayrak; jel', 'Scrim; difüzör', 'Reflektör; barn door'], 'Flag ışığı tümüyle keser, scrim ise ışığı azaltır. İkisi de çekimde ışığın biçimlendirilmesi için kullanılır.'),
  ('Bir ışık kaynağı özneden 2 metre uzaktayken 4 metre uzağa taşınırsa özneye düşen ışık şiddeti kaç kat azalır?', '4 kat', ['2 kat', '8 kat', '16 kat'], 'Işık şiddeti, mesafenin karesiyle ters orantılıdır. Mesafe iki katına çıkınca şiddet 1/4\'e iner.'),
  ('Bir tungsten lamba dimmerle kısıldığında ışığın rengi nasıl değişir?', 'Daha turuncu ve sıcak olur', ['Daha mavi ve soğuk olur', 'Beyaza döner ve renk sıcaklığı yükselir', 'Yeşile kayar ve doygunluk artar'], 'Telin sıcaklığı düştüğünde ışığın rengi kırmızı-turuncuya kayar. Bu nedenle tungsten lamba kısıldığında rengi değişir.'),
  ('Işık ölçerlerde \'olay ışığı\' ölçümü ile \'yansıyan ışık\' ölçümünün farkı nedir?', 'Olay ışığı özneye düşeni, yansıyan sahneden dönüşü ölçer', ['Olay ışığı yalnız gece, yansıyan ışık yalnız gündüz çalışır ve ölçüm yapamaz', 'Olay ışığı rengi, yansıyan ışık yalnız sesi ölçer', 'İkisi aynıdır, yalnız isimleri farklıdır ve değerleri değişmez'], 'Olay ışığı ölçerde küre özneye düşen ışığı alır, böylece yüzey rengi etkilemez. Yansıyan ışık ölçer ise sahne parlaklığını ölçer.'),
  ('Orta gri olarak kabul edilen ve pozlama ölçümünde referans olarak kullanılan kartın yansıtma oranı yaklaşık kaçtır?', 'Yüzde 18 yansıtma', ['Yüzde 50 yansıtma', 'Yüzde 8 yansıtma', 'Yüzde 90 yansıtma'], '18 yüzde gri kart, ortalama sahne parlaklığına denk kabul edilir. Pozlama ve renk dengesi için standart referans olur.'),
  ('\'Yanlış renk\' (false color) göstergesi pozlamada nasıl yardımcı olur?', 'Parlaklık seviyelerini renkle gösterir', ['Sesin seviyesini renkli gösterir', 'Odak mesafesini renkle belirler', 'Kare hızını ölçüp ekrana yansıtır'], 'False color, her pozlama düzeyine bir renk atar. Böylece ten rengi ya da aşırı parlak bölgeler kolayca kontrol edilir.'),
  ('DTS sistemini 1993\'te tanıtan ve \'Jurassic Park\' ile sinemaya taşıyan yöntemde ses nasıl saklanıyordu?', 'Ayrı CD\'lerde, zaman koduyla', ['Filmin kenarındaki mıknatıs şeritte ve optik iz olarak', 'Her karenin içine mikroskobik çentiklerle kazınarak', 'Plaklara kazınıp iğneyle okunarak, Vitaphone gibi'], 'DTS\'te ses ayrı CD\'lerde saklanır. Filmdeki zaman kodu, projektörün seslerle eşlenmesini sağlar.'),
  ('Bir film 24 kare/sn hızda ve zaman kodu 00:00:10:12 olan nokta, başlangıçtan itibaren kaçıncı kareye denk gelir?', '252 kare', ['240 kare', '264 kare', '126 kare'], '10 saniye x 24 = 240 kare; üzerine 12 kare eklenince 252 olur. Zaman kodu hesaplarında kare sayısı hızın katı olmalıdır.'),
  ('\'Er Ryan\'ı Kurtarmak\' (1998) filminin Omaha Plajı sahnesinde bir ara sesin boğuklaşıp yalnız ağır bir uğultu duyulması neyi anlatır?', 'Kaptan Miller\'ın şoku', ['Mikrofonun denize düştüğünü ve kaydın bozulduğunu', 'Filmde sesin hiç kullanılmadığını ve sahnenin sessiz olduğunu', 'Müzik kaydının teknik olarak bozulduğunu'], 'Öznel ses, karakterin algısını verir. Boğuk ses ve uğultu, savaş şokunun etkisini seyirciye aktarır.'),
  ('Dublaj stüdyosunda \'dudak eşleştirme\' sırasında en çok hangi unsurlara dikkat edilir?', 'Ağız şekilleri ve cümle süresi', ['Müziğin tonu ve ritim dengesi', 'Kamera açısı ve kadraj büyüklüğü', 'Işığın yönü ve sahnenin rengi'], 'Dublajcı, orijinal dudak hareketinin süresine ve belirgin ağız şekillerine uyan sözcükleri seçer. Böylece görüntü ile ses uyumlu görünür.'),
  ('1920\'lerde Iwan Serrurier\'in geliştirdiği ve kurgucuların film şeridini küçük bir ekranda ileri geri izleyip kesebildiği dik kurgu makinesinin adı nedir?', 'Moviola', ['Steenbeck, yatay masalı ve çok makaralı kurgu tezgâhı', 'Mutoskop, kartlı gösterim aygıtı', 'Nagra, taşınabilir ses kayıt cihazı'], 'Moviola, kurgucunun tek tek kareleri ve sesleri incelemesine olanak veren dik bir makineydi. Uzun yıllar Hollywood kurgu odalarının simgesi oldu.'),
  ('Avid Media Composer\'ın 1989\'da tanıtılması, kurgu teknolojisinde hangi dönüşümün başlangıcı sayılır?', 'Dijital doğrusal olmayan kurgu', ['Renkli filmin kurgu sürecine girmesi ve baskının kolaylaşması', 'Sesin görüntüden tümüyle ayrılması ve mono kaydın bitmesi', 'Kurgunun tamamen otomatikleşip kurgucuya gerek kalmaması'], 'Avid, görüntüleri dijital ortamda kurgulayıp kesmeden istenen sırada düzenlemeyi mümkün kıldı. Film makaralarını fiziksel olarak kesme ihtiyacı azaldı.'),
  ('Düşük çözünürlüklü kopyalarla yapılan kurgunun ardından orijinal yüksek çözünürlüklü görüntülerle aynı kurgunun yeniden oluşturulmasına ne denir?', 'Konform', ['Postviz', 'Telesine', 'Rotoskop'], 'Offline kurgu bitince EDL kullanılarak orijinal kaliteli kayıtlarla aynı kurgu yeniden kurulur. Buna conform adı verilir.'),
  ('Sessiz komedilerde hareketlerin modern TV\'de aşırı hızlı ve komik görünmesinin başlıca nedeni nedir?', 'Düşük hızla çekilip hızlı oynatılmaları', ['Işığın yetersiz kalıp görüntünün karanlık çıkması', 'Filmin ters oynatılması ve kopyalanması', 'Mikrofonların sesi yanlış kaydetmesi ve senkronun bozulması'], 'Sessiz filmler yaklaşık 16 kare/sn çekilirdi. 24 kare/sn ile oynatılınca hareket hızlanmış görünür.'),
  ('Bir yönetmen her iki dakikada bir kare çekip 24 saatlik güneşin hareketini 24 kare/sn hızda gösteriyor. Ortaya çıkan film kaç saniye sürer?', '30 saniye', ['60 saniye', '12 saniye', '48 saniye'], '24 saat = 1440 dakika; 1440 / 2 = 720 kare. 720 kare, 24 kare/sn hızında 30 saniye sürer.'),
  ('Saniyede 2000 kare çeken bir yüksek hızlı kameranın görüntüsü 25 kare/sn ile oynatılırsa hareket kaç kat yavaşlar?', '80 kat', ['20 kat', '8 kat', '200 kat'], '2000 / 25 = 80. Çok kısa süren patlama ya da damla düşüşü bu şekilde ayrıntılı izlenebilir.'),
  ('Kareleri çoğaltarak ya da araya yeni kareler üreterek yavaşlama elde eden dijital yöntemlere genel olarak ne ad verilir?', 'Zaman yeniden eşleme', ['Kare silme ve çıkarma', 'Renk anahtarlama ve maskeleme', 'Çift pozlama ve karıştırma'], 'Time remapping ile görüntünün hızı değiştirilebilir. Yazılım kareler arasında hareket analizi yaparak ara kareler üretir.'),
  ('Japon animesinde yaygın olan \'üçerli çekim\' (on threes) yönteminde saniyede kaç ayrı çizim kullanılır?', '8', ['12, çünkü her çizim iki kare gösterilir', '24, çünkü her kareye ayrı çizim yapılır', '6, çünkü her çizim dört kare gösterilir'], '24 kare/sn\'de her çizim üç kare gösterilirse saniyede 8 çizim gerekir. Bu yöntem haftalık dizilerde maliyeti ve emeği azaltır.'),
  ('Animede bir bölümün bütçesi sınırlı olsa da animatörlerin özenle çizdiği, olağanüstü akıcı kısa aksiyon ya da hareket anlarına ne ad verilir?', 'Sakuga', ['Ekonte denilen hikâye panosu', 'Banka denilen stok sahneler', 'OVA denilen video yapımları'], 'Sakuga, bir animatörün üstün çizim kalitesini sergilediği sahnelerdir. Hayranlar bu sahneleri sanatçının imzası olarak değerlendirir.'),
  ('İrlandalı Cartoon Saloon stüdyosunun \'Kells\'in Sırrı\' (2009) ve \'Kurt Gezginleri\' (2020) gibi filmlerini en çok hangi görsel özellik tanımlar?', 'Halk sanatına yaslanan çizim', ['Foto gerçekçi bilgisayar grafiği ve ışık', 'Kil figürlerle çekilen stop-motion düzeni', 'Rotoskopla gerçek oyuncu görünümü verilmesi'], 'Cartoon Saloon, İrlanda halk anlatılarını ve ortaçağ süsleme sanatını elle çizilmiş görsel dil hâline getirdi. Filmler Oscar\'a aday gösterildi.'),
  ('\'Sinema tarihinde en uzun yapım süresi geçiren animasyonlardan biri olarak anılan Richard Williams\'ın \'Hırsız ve Kunduracı\' hangi nedenle bilinir?', 'Onlarca yıllık yapım süreci', ['Yalnız ses efektleri kullanılması ve hiç görüntü olmaması', 'Tek bir kareyle yapılmış olması', 'Kısa sürede tamamlanıp gösterilmesi'], 'Film, Williams\'ın yıllar süren çalışmasına rağmen finansman sorunları nedeniyle tamamlanamadı. Dağıtımcılar sonradan başka versiyonlar çıkardı.'),
  ('Fleischer rotoskopunun 1915\'teki patentinden sonra Disney\'in \'Pamuk Prenses\' (1937) için bu yöntemi nasıl kullandığı söylenir?', 'Gerçekçi insan hareketi için', ['Tüm figürleri bilgisayardan çizmek için', 'Arka planları kilden yapıp çekmek için', 'Yalnız hayvanları canlandırıp renklendirmek için'], 'Disney animatörleri, gerçekçi insan hareketi için canlı oyuncu görüntülerini referans aldı. Bu gözlem, çizimin doğal görünmesine yardım etti.'),
  ('\'Masum Sanık Roger Rabbit\' (1988) çekimlerinde sette çizgi karakterlerin elindeki nesnelerin havada duruyormuş gibi görünmesi nasıl sağlandı?', 'Teller ve kuklacılar, sonra animasyon', ['Nesneler tümüyle bilgisayarda sonradan çizildi ve yerleştirildi', 'Oyuncular gerçek çizgi film kareleri içine yerleştirildi', 'Tüm sahneler kil figürlerle çekilip birleştirildi'], 'Setteki gerçek nesneler teller ve kuklacılarla oynatıldı. Animatörler sonra karakterleri bu hareketlere uyarladı; böylece nesneler ve karakter birlikte hareket ediyormuş gibi göründü.'),
  ('\'Hayalet Avcıları\' (1984) filmindeki ışın akımları (proton ışınları) nasıl yaratıldı?', 'Elle çizilen ışınlar optik baskıyla eklendi', ['Gerçek lazerlerle sette çekilerek ve yansıtılarak', 'Stop-motion kuklalarla kare kare çekilerek', 'Gerçek ateşle çekilip renklendirilerek'], 'Işınlar kare kare çizilerek animasyonla hazırlandı ve optik baskıyla canlı çekime eklendi. Her ışının dönen, kıvrılan hareketi çizim işidir.'),
  ('\'Jedi\'ın Dönüşü\' (1983) filmindeki hız motoru (speeder bike) kovalamacasında ormanın çok hızlı geçiyormuş gibi görünmesi nasıl sağlandı?', 'Steadicam yürüyüşü, düşük kare hızı', ['Bilgisayarla yaratılan orman ve araç modelleri', 'Mavi perde önünde çekilen maket araçlar', 'Helikopterden çekilen hızlı havadan görüntüler'], 'Garrett Brown, ormanda Steadicam\'le yürürken saniyede bir kare çekti ve görüntüyü normal hızda oynattı. Böylece yürüyüş çok hızlı bir uçuş gibi göründü.'),
  ('\'Kara Şövalye\' (2008) filmindeki hastane patlama sahnesi nasıl çekildi?', 'Gerçek bir binanın yıkılması', ['Maket binanın küçük ölçekte patlatılması', 'Bilgisayar efektiyle patlama yaratılması', 'Mavi perde önünde sahneyi çekip birleştirmek'], 'Nolan pratik efektleri tercih etti ve eski bir fabrika binasını gerçekten yıktırdı. Bu, sahnenin gerçekçiliğini artırdı.'),
  ('\'Başlangıç\' (Inception, 2010) filmindeki dönen koridor kavgası nasıl çekildi?', 'Gerçekten dönen koridor seti', ['Bilgisayarla yaratılan koridor çizimi', 'Kameranın baş aşağı çevrilmesi hilesi', 'Küçük maket koridorun çekilmesi ve büyütülmesi'], 'Ekip, dönebilen koridor seti inşa etti ve oyuncular gerçekten dönen duvar ve zeminde dövüştü. Bu yöntem sahnenin doğallığını sağladı.'),
  ('Roger Rabbit\'te çizgi karakterlerin canlı çekim ortamına uyması için hangi unsur animasyona sonradan eklendi?', 'Gölgeler ve ışık yansımaları', ['Ses efektleri ve müzik katmanları', 'Renk değiştirme ve renk bozulması', 'Hız değişimi ve zaman bükülmesi'], 'Sanatçılar, Toon karakterlerine ortamdaki ışığa uygun gölge ve parlaklık ekledi. Bu, karakterlerin gerçek dünyada duruyormuş gibi görünmesini sağladı.'),
  ('Spielberg\'in \'Üçüncü Türden Yakınlaşmalar\' (1977) filmindeki dev \'ana gemi\' sahnelerde nasıl yaratıldı?', 'Işık ve fiber optikli büyük maket', ['Bilgisayar animasyonuyla yaratılan model', 'Elle çizilmiş cel ile yapılmış çizim', 'Gerçek bir tekneye ışık takılarak'], 'Ana gemi, ışıklarla süslü ayrıntılı bir maketti. Douglas Trumbull\'un ekibi görüntüyü ışık efektleriyle birleştirdi.'),
  ('Matrix (1999) filminin kazandığı Oscar\'lar arasında aşağıdakilerden hangisi YER ALMAZ?', 'En İyi Yönetmen', ['En İyi Görsel Efekt', 'En İyi Kurgu', 'En İyi Ses Efektleri Kurgusu'], 'Matrix, Görsel Efekt, Kurgu, Ses ve Ses Efektleri Kurgusu dallarında dört Oscar kazandı. En İyi Yönetmen ödülünü kazanmadı.'),
  ('Edison\'un 1893\'te West Orange\'da kurduğu ilk film stüdyosu \'Black Maria\'nın en ilginç özelliği nedir?', 'Güneşi izleyecek biçimde dönmesi', ['Tamamen camdan yapılmış bir bina olması', 'Su üstünde yüzen bir tekne olması', 'Taşınabilir bir çadır biçiminde olması'], 'Black Maria, siyah ve katranlı yapısıyla tanınırdı; tavanı açılabiliyor ve bina güneş ışığına göre döndürülebiliyordu. Bu, ışıklandırma sorununun erken bir çözümüydü.'),
  ('Edison ile Biograph arasındaki 1900\'lerin patent savaşı sonunda ne gerçekleşti?', 'Patentler Şirketi\'nin kurulması', ['Biograph\'ın Fransa\'ya taşınması ve kapanması', 'Edison\'un bütün haklarını Lumière\'e satması', 'Filmlerin Amerika\'da tümüyle yasaklanması'], 'Rakip şirketler 1908\'de patentlerini birleştirip Motion Picture Patents Company\'yi kurdu. Bağımsız yapımcılar baskı altına alındı.'),
  ('Dijital sinema projektörlerinde Texas Instruments\'ın geliştirdiği DLP çipinin temel öğesi nedir?', 'Milyonlarca mikro ayna', ['Sıvı kristal film katmanları ve polarize süzgeçler', 'Dönen renkli cam plaka ve ışık tüneli', 'Lazer ışığını bölen prizma ve mercek dizisi'], 'DLP çipinde her bir ayna bir pikseli temsil eder ve ışığı perdeye ya da emiciye yönlendirmek için saniyede binlerce kez eğilir.'),
  ('Polarize 3D gösterimlerinde gümüş perde kullanılmasının nedeni nedir?', 'Polarizasyonu koruması', ['Perdeyi çok daha ucuza yapabilmesi', 'Işığı tümüyle yutup gölgeyi artırması', 'Ses yalıtımını ve yansımayı artırması'], 'Beyaz mat perde polarizasyonu bozar ve iki göz görüntüsü karışır. Gümüş kaplama polarizasyonu korur.'),
  ('Çoğu sinema salonunda perdenin üzerindeki ince delikler ne işe yarar?', 'Sesin perde arkasından geçmesi', ['Işığın dağılmasını engelleyip parlaklığı artırması', 'Perdenin ağırlığını hafifletip asılmasını kolaylaştırması', 'Böceklerin salona girmesini ve perdeye konmasını önlemesi'], 'Perde arkasına yerleştirilen ana hoparlörlerin sesi, mikroskobik deliklerden geçerek izleyiciye ulaşır. Ses ve görüntü aynı noktadan geliyormuş gibi algılanır.'),
  ('Güney Koreli CJ 4DPlex\'in geliştirdiği, koltukların hareket ettiği ve rüzgâr, su ve koku efektlerinin eklendiği sinema sistemi hangisidir?', '4DX', ['IMAX', 'Dolby Cinema', 'THX'], '4DX, perdedeki aksiyona eşzamanlı koltuk hareketi ve çevresel efektler ekler. ScreenX\'i de aynı şirket geliştirmiştir.'),
  ('Video kayıtlarında 4:2:0 renk örnekleme ne anlama gelir?', 'Renk bilgisi iki yönde yarıya iner', ['Renk bilgisi hiç saklanmaz ve görüntü siyah-beyaza döner', 'Parlaklık bilgisi yarıya indirilir ve renk korunur', 'Yalnızca yeşil kanal tutulur ve diğerleri atılır'], 'Gözün parlaklığa renkten daha duyarlı olduğu varsayımıyla renk çözünürlüğü azaltılır. Böylece dosya boyutu küçülür.'),
  ('8 bit renk derinliğinde her bir RGB kanalı 256 düzeyde değer alır. Üç kanalın toplam renk sayısı yaklaşık kaçtır?', 'Yaklaşık 16,7 milyon', ['Yaklaşık 1,6 milyon renk', 'Yaklaşık 256 bin renk', 'Yaklaşık 4,3 milyar renk'], '256 x 256 x 256 = 16.777.216. 10 bit renkte kanal başına 1024 düzey olur, toplamı yaklaşık 1,07 milyardır.'),
  ('Sinemadaki 24 kare/sn ile televizyondaki 23,976 kare/sn arasındaki küçük farkın kaynağı nedir?', 'NTSC\'deki 1000/1001 katsayısı', ['Mikrofonun kayıt hızındaki küçük sapma', 'Projektörün mekanik aşınması ve yavaşlaması', 'Renkli film bandının doğal yavaşlığı'], 'NTSC renkli televizyon yayınında hızlar 1000/1001 oranında azaltıldı. 24 x 1000/1001 yaklaşık 23,976 eder.'),
  ('Ultra HD (UHD) televizyonda \'4K\' yatay çözünürlüğü kaçtır?', '3840 piksel', ['4096 piksel', '2560 piksel', '7680 piksel'], 'UHD 3840 x 2160\'tır. DCI 4K ise 4096 x 2160 çözünürlüğündedir.'),
  ('Tek kare görüntü sıkıştırmasında kare başına bilgi aynı kalıyorsa, \'sadece iç kare\' (all-intra) kayıt ne avantaj sağlar?', 'Karelerin bağımsız işlenmesi', ['Dosya boyutunun çok küçük olması ve hafızanın azalması', 'Görüntünün renksiz olması ve gri tonda kaydı', 'Ses kalitesinin artması ve gürültünün azalması'], 'All-intra kayıtta her kare tek başına kodlanır. Kurgu yazılımı kareler arası bilgiyi çözmek zorunda kalmaz.'),
  ('Arşivcilerin renkli filmleri korumak için sıklıkla yaptıkları, her renk kanalı için ayrı siyah-beyaz film kopyası oluşturma işlemine ne denir?', 'Renk ayrışımı', ['Renk karıştırma', 'Çift pozlama', 'Optik dönüştürme'], 'Renkli boyalar zamanla solar; siyah-beyaz gümüş görüntüler ise çok daha kalıcıdır. Üç renk ayrışımı, renkleri sonradan yeniden birleştirmeyi mümkün kılar.'),
  ('1950-70 yılları arasında Eastmancolor baskılarının zamanla pembe ya da kırmızıya kaymasının nedeni nedir?', 'Sarı ve camgöbeği boyaların solması', ['Gümüş görüntünün ışıkta oksitlenmesi ve kararması', 'Selüloz tabanın yırtılması ve kırılması', 'Işığın şeridi yakıp kopyayı eritmesi'], 'Eski renkli filmlerdeki boyalar eşit hızda solmaz; magenta daha kalıcı olduğundan görüntü pembe-kırmızıya kayar.'),
  ('Prodüksiyon tasarımcısı ile set dekoratörü arasındaki fark nedir?', 'Biri görünümü, öbürü döşemeyi yönetir', ['Biri ışığı, öbürü sesi yönetir ve kaydeder', 'Biri kamerayı, öbürü kurgu ve renk yapar', 'İkisi aynı işi yapar ve unvan farkı yoktur'], 'Prodüksiyon tasarımcısı sanat bölümünün başındadır. Set dekoratörü ise mekânın mobilya, halı ve aksesuarlarını seçer.'),
  ('Renk düzenlemede \'birincil düzeltme\' ile \'ikincil düzeltme\' arasındaki temel fark nedir?', 'Birincisi tüm kareyi, ikincisi seçili bölgeyi etkiler', ['Birincisi yalnız sesi, ikincisi yalnız görüntüyü etkiler', 'Birincisi kamerada, ikincisi projektörde yapılır', 'Birincisi siyah-beyazda, ikincisi renkli filmde yapılır'], 'Primary düzeltme tüm görüntünün genel dengesini ayarlar. Secondary düzeltme ise belirli bir rengi ya da alanı izole edip yalnız onu değiştirir.'),
  ('Log biçiminde kaydedilen bir görüntünün düz, soluk ve düşük kontrastlı görünmesinin nedeni nedir?', 'Geniş aralığı küçük alana sıkıştırması', ['Kameranın bozuk olması ve sensörün arızalanması', 'Filmin ışığı yutması ve kayıt etmemesi', 'Sensörün siyah-beyaz kayıt yapması ve renk bilgisini atması'], 'Log eğrisi, gölge ve parlak alan ayrıntısını kaybetmemek için tonları sıkıştırır. Görüntü, renk düzenlemede ya da LUT ile normal görünüme çevrilir.'),
  ('Kontrast eğrisini \'S\' biçimine getirmek görüntüde hangi etkiyi yaratır?', 'Gölgeler koyulur, parlaklar açılır', ['Görüntü tümüyle soluklaşır ve gri görünür', 'Renkler siyah-beyaza döner ve doygunluk kaybolur', 'Görüntü bulanıklaşır ve netlik düşer'], 'S eğrisi orta tonları sabit tutarak uçları iter. Sonuç daha dramatik ve ayrıntılı bir kontrast hissidir.'),
  ('\'Avatar: Suyun Yolu\' (2022) filminde yüksek kare hızı nasıl kullanıldı?', 'Bazı sahnelerde 48, bazılarında 24', ['Bütün film 120 kare/sn olarak gösterildi ve çekildi', 'Yalnız müzik sahnelerinde farklı hız kullanıldı', 'Hiçbir sahnede yüksek hız kullanılmadı ve kayıt bozuldu'], 'Cameron, aksiyon sahnelerinde kare hızını yükseltip diğer sahnelerde 24\'te tutmuştu. Böylece hem akıcı hem sinematik his korundu.'),
  ('Televizyonlardaki \'hareket yumuşatma\' (motion smoothing) özelliğinin sinema görüntüsünde yarattığı yaygın şikâyet nedir?', 'Filmin video gibi görünmesi', ['Sesin sürekli kesilmesi ve gecikmesi', 'Renklerin tümüyle silinmesi ve griye dönmesi', 'Görüntünün ters dönmesi ve çevrilmesi'], 'Yazılım ara kareler üretip akıcılığı artırır. Bu, sinemanın karakteristik hareket görünümünü bozarak \'pembe dizi etkisi\' yaratır.'),
  ('Hulk (2003) karakterinin yeşil bedeninin hareketi nasıl hazırlanmıştır?', 'Oyuncu hareketinin dijital figüre aktarılması', ['Boyalı kuklaların stop-motion ile çekilmesi ve boyanması', 'Gerçek ölçekte dev bir mekanik robot yapılması', 'Yalnızca elle çizilmiş çizgi film karelerinin birleştirilmesi'], 'Ang Lee\'nin filmi, Hulk\'ı bilgisayarla yarattı ve oyuncunun hareketini referans aldı. Büyüklük ve ağırlık duygusu dijital olarak sağlandı.'),
  ('Bir efekt ekibinin, süper kahramanın pelerinini rüzgârda gerçekçi dalgalandırması için bilgisayarda kullandığı yöntem hangisidir?', 'Kumaş benzetimi', ['Doku haritalama', 'Kemik iskelet düzeni', 'Işın izleme'], 'Kumaş benzetimi, ağırlık, rüzgâr ve çarpışma gibi fiziksel kuvvetleri hesaba katarak giysi hareketini oluşturur.'),
  ('ZBrush\'ın sinema ve oyun sanatında yaygın kullanımının nedeni nedir?', 'Heykel gibi ayrıntılı modelleme', ['Kurgu için hızlı ve hafif bir yazılım olması', 'Ses mikserinin dijital karşılığı olması', 'Kamera takibi ve sahne çözümlemesi sunması'], 'ZBrush, sanatçının dijital kil gibi yüzeyi şekillendirmesini sağlar. Yaratık ve karakter modellemelerinde ince ayrıntı eklemek için kullanılır.'),
  ('Pixar\'ın geliştirdiği ve sahne verilerini farklı yazılımlar arasında paylaşmayı sağlayan açık formatın adı nedir?', 'USD', ['MP4', 'DCP', 'XML-EDL'], 'USD, karmaşık sahne bilgisini katmanlı biçimde tutar ve çok sayıda sanatçının aynı sahneyle çalışmasına izin verir. Sinema ve oyun sektöründe yaygınlaşmıştır.'),
  ('Bilgisayar animasyonunda \'shader\' (gölgelendirici) neyi belirler?', 'Yüzeyin ışığa tepkisi', ['Karakterin ses tonu ve konuşma biçimi', 'Kameranın hareket yolu ve açısı', 'Filmin toplam süresi ve kare sayısı'], 'Shader, yüzeyin matlık, parlaklık ve saydamlık gibi özelliklerini tanımlar. Aynı model farklı shaderlarla çok farklı görünür.'),
  ('Bir efekt sanatçısı sahneye yapay yağmur eklerken parçacıkların rüzgârdan ve yerçekiminden etkilenmesini sağlıyor. Bu işlem hangi kavramın örneğidir?', 'Fiziksel benzetim', ['Rotoskop çizimi', 'Kamera takibi', 'Renk anahtarlama işlemi'], 'Bilgisayar fiziği, yağmur damlalarını yerçekimi ve rüzgâr gibi kuvvetlere göre hareket ettirir.'),
  ('Bir 3D animatörün \'animasyon eğrisi\' (graph editor) üzerinde ayar yapmasının amacı nedir?', 'Hareketin hızlanma biçimini ayarlamak', ['Ses seviyesini ve dengesini ayarlamak', 'Rengi değiştirmek ve doygunluğu artırmak', 'Kareleri silmek ve süreyi kısaltmak'], 'Eğriler, bir değerin zaman içinde nasıl değiştiğini gösterir. Eğim ve biçim, hareketin doğal ya da mekanik görünmesini belirler.'),
  ('Bir odanın dikdörtgen göründüğü bakış noktasından bakıldığında içindeki iki kişiden birinin devasa, diğerinin minik görünmesini sağlayan yanılsama düzeneğine ne ad verilir?', 'Ames odası', ['Ayna labirenti', 'Dönen oda', 'Kaydırmalı set'], 'Ames odası aslında yamuk biçimli bir odadır ama belirli bir noktadan bakıldığında dikdörtgen görünür. Uzaklık algısı bozulduğundan insanlar farklı boyda görünür.'),
  ('Kubrick\'in \'Cinnet\' (1980) filminde Danny\'nin üç tekerlekli bisikletiyle otel koridorlarında gezdiği sahnelerde kamera nasıl çalıştı?', 'Zemine yakın Steadicam', ['Raylar üzerinde ilerleyen bir dolly ile', 'Vinçle yukarıdan yavaşça inen kamerayla', 'Elde sallanan hafif bir kamerayla'], 'Garrett Brown, Steadicam\'i zemine yakın konumda taşıyarak bisiklet tekerleklerinin hızına uyum sağladı. Akıcı ve gerilimli bir takip elde edildi.'),
  ('Norman McLaren\'ın \'Pas de Deux\' (1968) filminde dansçıların izli, yankılı görünümünü yaratan yöntem nedir?', 'Optik baskıda kare yineleme', ['Çizim ve cel kullanımı yoluyla elle boyama', 'Pikselasyon ile gerçek dansçıların çekilmesi', 'Kum animasyonu ile ışık masasında hareket'], 'Dans görüntüsü yüksek kontrastla çekildi ve optik baskıyla kareler üst üste bindirildi. Hareketin iz bıraktığı bir efekt elde edildi.'),
  ('Norman McLaren\'ın \'Synchromy\' (1971) filminde ses nasıl üretildi?', 'Optik ize çizilen desenler', ['Müzik gruplarının stüdyo kaydı yoluyla', 'Plak kaydı ile elde edilen eşzamanlı ses', 'Bilgisayarlı sentezleyici ile elde edilen sesler'], 'McLaren, ses şeridinin kenarına belli desenler çizdi ve projektör bunları ses olarak okudu. Görüntü ve ses aynı deseni paylaştı.'),
  ('Frédéric Back\'in \'Crac!\' (1981) ve \'Ağaç Dikmiş Adam\' (1987) filmlerinin ayırt edici görsel tekniği nedir?', 'Cel üzerinde renkli kalem', ['Bilgisayarda vektör çizim çalışmaları', 'Kilden yapılmış küçük figürler ve sahneler', 'Kâğıt kesme ile oluşturulmuş siluet sahneler'], 'Back, buğulu görünüm veren cel yüzeyine renkli kalemle çizdi. Bu yöntem, filmlerine yumuşak ve dokulu bir estetik kazandırdı.'),
  ('Karel Zeman\'ın 1958 tarihli \'Yıkım İçin Bir İcat\' filmi nasıl bir görsel stile sahiptir?', 'Gravür stilinde karma çekim', ['Tümüyle siyah-beyaz stop-motion üslubu', 'Doğal ışıklı belgesel üslubu ve el kamerası', 'Soyut ve boyalı doğrudan film üslubu'], 'Zeman, Jules Verne gravürlerini andıran çizimleri canlı oyuncularla ve maketlerle birleştirdi. Çok katmanlı bir görsel yanılsama elde etti.'),
  ('Aydınlatmada \'yüksek anahtar\' (high key) ışıklandırmanın başlıca görsel özelliği nedir?', 'Az gölgeli, aydınlık görüntü', ['Çok koyu, yüksek kontrastlı ve gölgeli görüntü', 'Yalnızca siluet ve kenar ışıklı görüntü', 'Yalnızca kenar ışığıyla çekilmiş koyu görüntü'], 'High key, ışık oranını düşük tutar ve gölgeleri yumuşatır. Komedi, müzikal ve neşeli sahnelerde kullanılır.'),
  ('\'Motive edilmiş ışık\' (motivated lighting) ne demektir?', 'Kaynağı sahnede gösteren ışık', ['Işığın rastgele yönlendirilip dağıtılması ve yansıtılması', 'Yalnızca gün ışığıyla yapılan çekim', 'Işığın kamerayla birlikte hareket etmesi ve dönmesi'], 'Motive edilmiş ışık, lamba ya da pencere gibi sahne içindeki kaynağı mantıklı kılan yönde ve renkte kurulur. Gerçeklik hissi verir.'),
  ('Bir yönetmen sahnenin ışığını \'dramatik ve yüksek kontrastlı\' istiyor. Hangi ışık oranını tercih etmesi daha olasıdır?', 'Yaklaşık 8:1 oranı', ['Yaklaşık 1:1 oranı', 'Yaklaşık 2:1 oranı', 'Yaklaşık 1:2 oranı'], 'Yüksek oran, gölgelerin çok koyu kalmasına neden olur. 8:1 gibi oranlar yüksek kontrastlı, dramatik görünüm verir.'),
  ('Işık oranı 2:1 olan bir portre sahnesi nasıl bir görünümdür?', 'Yumuşak, gölgesi hafif', ['Çok sert, siyah gölgeli', 'Tamamen siluet', 'Işık olmayan karanlık'], 'Düşük ışık oranı ana ve dolgu ışığı arasındaki farkı küçük tutar. Sonuç yumuşak ve sakin bir görüntüdür.'),
  ('Bir sahnede tavandan sarkan lamba ve masa lambaları gerçek ışık verirken, bu kaynakların yetersizliğini gidermek için gizli büyük lambalarla ışığı güçlendirmek hangi uygulamadır?', 'Pratik ışıkların güçlendirilmesi', ['Negatif dolgu ile gölge derinleştirme', 'Çift pozlama ile görüntü karıştırma', 'Gece çekiminde filtre ile gündüz taklidi'], 'Pratik lambalar zayıf olduğunda gizli kaynaklarla desteklenir. Böylece sahne gerçek lambalardan aydınlanıyormuş gibi görünür.'),
  ('Bir yönetmen gün batımı sahnesini yalnız on dakika içinde çekmek zorunda. Ekibin hazırlığı için en önemli planlama nedir?', 'Önceden hazırlık ve prova', ['Çekimde hiçbir ışık kullanmama kararı', 'Kamerayı sabit bırakıp prova yapmama', 'Oyuncuları son dakikada çağırıp çekme'], 'Doğal ışık kısa sürede değişir. Prova, ışık ölçümü ve ekipman hazırlığı yapılmazsa uygun görüntü elde edilemez.'),
  ('Saniyede 25 kare çeken bir kamerada obtüratör açısı 180 derece ise her karenin pozlama süresi kaç saniyedir?', '1/50 saniye', ['1/25 saniye', '1/100 saniye', '1/200 saniye'], 'Pozlama süresi = açı / (360 x kare hızı) = 180 / (360 x 25) = 1/50 saniyedir.'),
  ('Diyafram f/2\'den f/8\'e kapatılırsa sensöre ulaşan ışık kaç kat azalır?', '16 kat', ['4 kat', '8 kat', '32 kat kadar'], 'f/2\'den f/8\'e gitmek 4 durak demektir: f/2, 2,8, 4, 5,6, 8. Her durak ışığı yarıya indirdiği için 2 üzeri 4 = 16 kat azalır.'),
  ('Bir sahnede f/4, 1/50 saniye, ISO 800 ile doğru pozlama alınıyor. Diyafram f/2,8\'e açılırsa pozlamayı korumak için enstantane yaklaşık ne olmalıdır?', '1/100 saniye', ['1/25 saniye', '1/200 saniye', '1/50 saniyeden uzun'], 'f/4\'ten f/2,8\'e geçmek bir durak fazla ışık demektir. Aynı pozlama için enstantane yarıya, yani 1/100 saniyeye indirilir.'),
  ('ND 0,9 değerli bir nötr yoğunluk filtresi kaç durak ışık keser?', '3 durak', ['2 durak', '6 durak', '9 duraktan fazla'], 'Her 0,3 yoğunluk bir duraktır. 0,9 / 0,3 = 3 durak, yani ışık sekizde bire düşer.'),
  ('100 Mbit/sn bit hızıyla 10 dakikalık bir video kaydedilirse dosya boyutu yaklaşık kaç gigabayttır?', '7,5 GB', ['1 GB', '75 GB', '750 MB kadar'], '100 Mbit/sn x 600 sn = 60.000 Mbit; bunu 8\'e bölünce 7.500 MB, yani 7,5 GB olur.'),
  ('48 kHz, 24 bit, stereo sıkıştırılmamış ses bir dakikada yaklaşık kaç megabayt yer kaplar?', '17,3 MB', ['5,8 MB', '86,4 MB', '1,7 MB civarı'], '48.000 x 3 bayt x 2 kanal x 60 sn = 17.280.000 bayt, yani yaklaşık 17,3 MB\'dir.'),
  ('90 dakikalık bir film 35 mm 4-perf film üzerinde 24 kare/sn ve fitte 16 karelik yoğunlukla basılırsa film uzunluğu yaklaşık kaç fittir?', '8100 fit', ['900 fit', '4050 fit', '16200 fit'], '90 dk = 5400 sn; x 24 = 129.600 kare; 16 kare/fit ile bölününce 8100 fit eder.'),
  ('DCI 4K (4096 x 2160) bir karede yaklaşık kaç piksel vardır?', '8,85 milyon', ['2,2 milyon', '8,3 milyon', '33,2 milyon kadar'], '4096 x 2160 = 8.847.360 pikseldir. UHD 4K (3840 x 2160) ise 8.294.400 pikseldir.'),
  ('10 bit RGB renk derinliğinde teorik renk sayısı yaklaşık kaçtır?', '1,07 milyar', ['16,7 milyon', '256 milyon', '4,29 milyar kadar'], 'Kanal başına 1024 düzey vardır; 1024 üzeri 3 = 1.073.741.824\'tür.'),
  ('Saniyede 25 kare zaman kodu 00:01:30:10, başlangıçtan itibaren kaçıncı kareyi gösterir?', '2260 kare', ['2250 kare', '2410 kare', '2290 kareden fazla'], '1 dk 30 sn = 90 sn; 90 x 25 = 2250; 10 kare eklenince 2260 olur.'),
  ('Bir ışık kaynağı özneden 1 metre uzaktan 3 metre uzağa taşınırsa özneye düşen aydınlık yaklaşık kaç katına düşer?', 'Dokuzda bire', ['Üçte bire', 'Altıda bire', 'Yarısına, yani iki kat düşer'], 'Işık şiddeti mesafenin karesiyle ters orantılıdır. 3\'ün karesi 9 olduğundan aydınlık dokuzda bire iner.'),
  ('Bir yönetmen cam arkasındaki bir kişiyi çekerken camdaki yansımaları azaltmak istiyor. Objektife hangi filtreyi takmalıdır?', 'Polarize filtre', ['Nötr yoğunluk filtresi, ışığı azaltan', 'Pro-mist filtresi, ışığı yumuşatan', 'Yeşil renk filtresi, tonları değiştiren'], 'Polarize filtre, belirli yönlü yansımaları engeller. Camdaki ve sudaki yansımalar azalır; gökyüzü de daha koyu mavi görünür.'),
  ('Pro-Mist ve benzeri difüzyon filtreleri görüntüye ne ekler?', 'Parlak alanlar çevresinde yumuşak ışıma', ['Daha yüksek keskinlik ve çok sert kontrast', 'Daha çok renk doygunluğu ve canlılık', 'Belirgin hareket bulanıklığı etkisi'], 'Difüzyon filtreleri, parlak ışık kaynaklarının çevresine hafif bir hale ekler ve yüzleri yumuşatır. Dijital görüntünün sertliğini azaltmak için de kullanılır.'),
  ('Gökyüzünün çok parlak, yer planının ise koyu olduğu bir manzarada, parlak bölümü kısmak için hangi filtre kullanılır?', 'Dereceli ND filtresi', ['Polarize filtre, yansımayı azaltan', 'Turuncu filtre, ısıyı artıran', 'Siyah-beyaz filtre, rengi kaldıran'], 'Dereceli ND, filtrenin yarısı koyu, yarısı şeffaftır. Gökyüzü kısılır, yer planı etkilenmez; böylece pozlama dengelenir.'),
  ('Odak çekici (1. kamera asistanı) objektif halkasına neden bant işaretleri koyar?', 'Duruş noktalarının önceden işaretlenmesi', ['Işık değerini ölçmek ve not almak', 'Obtüratör açısını ayarlayıp kaydetmek', 'Sesi senkron edip kaydı başlatmak'], 'Odak mesafeleri oyuncunun duracağı noktalara göre işaretlenir. Çekim sırasında bu işaretler arasında odak kaydırılır.'),
  ('Sabit (prime) objektiflerin zum objektiflere göre sinemada tercih edilme nedenlerinden biri nedir?', 'Daha geniş diyafram ve yüksek kalite', ['Her zaman çok daha ucuz olmaları ve hafif olmaları', 'Çekimde odak uzaklığını anında değiştirebilmeleri', 'Hiç ışık kaybetmemeleri ve perdeyi aydınlatmaları'], 'Prime objektifler daha basit optik tasarıma sahiptir. Daha az ışık kaybederler ve yüksek keskinlik sağlarlar.'),
  ('Bir sinemacı nesneyi uzaktan yakın gösterip arka planı çok bulanık yapmak istiyor. Hangi kombinasyon bu sonucu verir?', 'Uzun odak ve açık diyafram', ['Kısa odak uzaklığı ve kapalı diyafram', 'Orta odak uzaklığı ve çok yüksek ISO', 'Geniş açı objektif ve ND filtre'], 'Uzun objektif ve açık diyafram alan derinliğini azaltır. Arka plan bulanıklaşır ve özne öne çıkar.'),
  ('Televizyon ekranının görüntüsünü kamerayla çekerken görüntüde yatay koyu bantların kayması neyin sonucudur?', 'Ekran yenileme hızı uyuşmazlığı', ['Sesin görüntüyle çakışması ve senkron kaybı', 'Kablonun zayıf olması ve görüntü gürültüsü', 'Odak halkası sorunu ve netlik kaybı'], 'Ekran belirli hızda yenilenir; kamera obtüratörü bu hızla eş olmazsa bantlar belirir. Senkron tarama ayarı sorunu giderir.'),
  ('Bir yönetmen sahnede mum ışığı hissi vermek için lambayı hangi renk sıcaklığına yakın seçmelidir?', 'Yaklaşık 1800-2000 K', ['Yaklaşık 5600 K', 'Yaklaşık 9000 K', 'Yaklaşık 12000 K'], 'Mum alevi çok sıcak, turuncu renkte ışık verir ve renk sıcaklığı yaklaşık 1800 K civarındadır. Mavi tonlar gün ışığına aittir.'),
  ('Bilgisayar grafiğinde \'render süresi\' neden stüdyolar için önemli bir bütçe kalemidir?', 'Her kare saatlerce hesaplanabilir', ['Kareler kendi kendine boyandığı için hızlıdır ve ucuzdur', 'Sesler tek tek render edildiği için uzun sürer', 'Çekimler ters çevrildiği için yavaştır'], 'Yüksek ayrıntılı sahneler çok işlem gücü ister. Render çiftliklerini çalıştırmak maliyetli olduğundan sürenin kısaltılması önemlidir.'),
  ('1919\'da Pat Sullivan\'ın stüdyosunda Otto Messmer tarafından yaratılan, sessiz dönemin en popüler çizgi film karakterlerinden biri hangisidir?', 'Felix the Cat karakteri', ['Mickey Mouse karakteri', 'Betty Boop karakteri', 'Bugs Bunny karakteri'], 'Felix, hızlı ve esprili animasyon dizileriyle sessiz sinema döneminin en tanınmış çizgi film karakteri oldu. Sinema, televizyon ve ürünlerle ünlendi.'),
  ('Lumière\'in sinematografının Edison\'un kinetoskopuna göre ticari üstünlüğü hangi özelliğiyle ilgiliydi?', 'Taşınabilir, çok işlevli aygıt olması', ['Renkli görüntü vermesi ve boyalı olması', 'Sesli çalışması ve plakla uyumlu olması', 'Yalnızca stüdyoda çalışması ve ağır olması'], 'Sinematograf elle çevrilirdi ve aynı aygıt üç iş görürdü. Bu esneklik, dünyanın dört bir yanında çekim ve gösterim yapılmasını kolaylaştırdı.'),
  ('Disney\'in \'Karlar Ülkesi\' (2013) filmindeki karın gerçekçi birikmesi ve dağılması için geliştirilen simülasyon yazılımının adı nedir?', 'Matterhorn kar yazılımı', ['Hyperion render yazılımı', 'Presto animasyon yazılımı', 'Houdini simülasyon yazılımı'], 'Disney, karın hacmini ve çarpışmalarını hesaplayan Matterhorn adlı bir kar simülasyonu geliştirdi. Film boyunca yağan, savrulan ve yığılan kar bu yazılımla elde edildi.'),
  ('Disney\'in \'Büyük Kahraman 6\' (2014) filmiyle ilk kez kullandığı yeni işleme (render) yazılımının adı nedir?', 'Hyperion', ['Matterhorn', 'RenderMan', 'Nuke'], 'Hyperion, karmaşık sahnelerde ışığın yoğun biçimde hesaplanmasını sağlar. Disney sonraki filmlerinde de kullandı.'),
  ('Chris Wedge\'in 1998 tarihli, Oscar kazanan \'Bunny\' kısa filminin teknik açıdan önemi nedir?', 'Gerçekçi global aydınlatma', ['Tümüyle elle çizilmiş kareler', 'Gerçek tavşanın canlı çekimi', 'Yalnız siyah-beyaz çekilmiş görüntü'], 'Bunny, Blue Sky\'ın geliştirdiği ışık hesaplama yöntemiyle yapıldı. Film, stüdyonun ilerleyen yıllardaki uzun metrajları için temel oldu.'),
  ('Nick Park\'ın 1989\'da Oscar kazanan kısa filmi \'Creature Comforts\' nasıl bir fikre dayanır?', 'Gerçek röportaj seslerinin kile söylettirilmesi', ['Sessiz bir hayvanat bahçesi gezisinin anlatılması', 'Bir uzay yolculuğunun komik biçimde canlandırılması', 'Bir korku masalının kil figürlerle işlenmesi'], 'Film, hayvanat bahçesindeki hayvanların yaşamı hakkında konuşan sıradan insan seslerinin kil hayvan figürlerine yerleştirilmesine dayanır. Aardman\'ın mizah anlayışını yansıtır.'),
  ('Wallace ve Gromit\'in ilk filmi \'Bir Büyük Gün\' (A Grand Day Out, 1989) nasıl başlamış bir projedir?', 'Film okulunda başlayan öğrenci projesi', ['Disney\'in sipariş ettiği bir film projesi', 'Bir televizyon reklamı projesi', 'Bir tiyatro oyunu uyarlaması projesi'], 'Park, filmi National Film and Television School\'da öğrenciyken başlattı ve Aardman\'da tamamladı. Film Oscar\'a aday oldu.'),
  ('1933 yapımı \'King Kong\' filminde canlı oyuncular ile Kong\'u aynı karede göstermek için Willis O\'Brien hangi yöntemi kullandı?', 'Minyatür arka projeksiyon', ['Üç boyutlu stereoskopik çekim', 'Bilgisayar benzetimi', 'Yalnız çizim animasyonu'], 'Oyuncuların görüntüsü, minyatür sahnenin arkasındaki küçük perdeye yansıtıldı. Böylece kare kare hareket ettirilen Kong ile oyuncular aynı karede göründü.'),
  ('Ed Catmull\'un 1974\'te geliştirdiği Z-tamponu (Z-buffer) yöntemi bilgisayar grafiğinde ne işe yarar?', 'Hangi yüzeyin önde olacağını belirler', ['Sesi ve görüntüyü senkronlar ve eşler', 'Kare hızını yükseltir ve akıcılık verir', 'Renkleri doğal hâle getirir ve dengeler'], 'Z-tamponu her piksel için derinlik değerini saklar. Önde bulunan nesne arkada kalanı örter ve gizli yüzeyler doğru çizilir.'),
  ('Alvy Ray Smith ve Ed Catmull\'un geliştirdiği alfa kanalı (alpha channel) hangi sorunu çözmeye yöneliktir?', 'Saydamlıkla birleştirmek', ['Seslerin senkronunu sağlamak ve eşlemek', 'Film hızını ayarlamak ve belirlemek', 'Renk sıcaklığını ölçmek ve dengelemek'], 'Alfa kanalı, her pikselin saydamlık bilgisini saklar. Görüntü katmanlarının birleştirilmesinde kenarların temiz kalması için gereklidir.'),
  ('Cinerama sisteminde üç ayrı projektörün görüntülerinin perdede birleştiği yerlerde seyirciyi en çok rahatsız eden teknik sorun neydi?', 'Dikiş çizgilerinin görünmesi', ['Seslerin görüntüden gecikmesi ve senkron kayması', 'Renklerin tümüyle silinmesi ve griye dönmesi', 'Perdenin yırtılması ve yıpranması'], 'Üç görüntünün kenarları tam hizalanamadığı için perdede kesişme çizgileri belirirdi. Bu sorun, sonraki tek şeritli 70 mm sistemlerinde yoktu.'),
  ('Bolex H16 gibi kameraların öğrenci ve deneysel sinemada tercih edilme nedeni nedir?', 'Yaylı, hafif ve ucuz 16 mm kamera', ['Dijital kayıt yapan ve kartlı kamera', 'Çok kanallı ses kaydeden stüdyo kamerası', 'IMAX filmi çekebilen büyük kamera'], 'Bolex, yay kurmalı çalıştığı için pile ihtiyaç duymazdı. Hafif ve dayanıklı yapısıyla bağımsız sinemacıların başlıca aracıydı.'),
  ('Dublörlerin yangın sahnelerinde giydiği, aleve dayanıklı kumaşın adı nedir?', 'Nomex', ['Kevlar yelek', 'Lycra', 'Polarize kumaş'], 'Nomex, ısıya dayanıklı bir liftir. Yangın sahnelerinde dublörler bu kumaştan yapılmış iç giysiler giyer; üzerine jel ve ateş uygulanır.'),
  ('\'2001: Bir Uzay Destanı\'nda Discovery gemisindeki koşu sahnesi için yapılan döner dev set nasıl çalıştı?', 'Gerçekten dönen tambur', ['Bilgisayarla çizilmiş koridor görüntüsü', 'Filmin ters çekilmesi hilesi', 'Mavi perde önünde yapılan koşu çekimi'], 'Kubrick\'in ekibi, döner bir tambur inşa etti. Oyuncu koşarken tambur dönüyor, kamera da onunla birlikte hareket ediyordu.'),
  ('Animasyonda \'çekicilik\' (appeal) ilkesi ne anlama gelir?', 'Karakterin ilgi uyandırması', ['Karakterin yalnızca sevimli çizilmesi gerektiği', 'Karakterin hep gülümsemesi gerektiği', 'Karakterin hiç hareket etmemesi gerektiği'], 'Appeal, kötü karakterlerin bile ilgi çekici olabilmesidir. Net siluet, ilginç tasarım ve kişilik bu ilkenin parçasıdır.'),
  ('Animasyonda \'abartı\' (exaggeration) ilkesi nasıl uygulanmalıdır?', 'Gerçeğin biraz ötesi ama inandırıcı', ['Gerçeklikle hiçbir ilişkisi olmayacak biçimde abartmak', 'Hareketi tümüyle küçültüp ifadeyi silmek', 'Yalnız renklerle ve ışıkla abartmak'], 'Abartı, duyguyu ve hareketi vurgular. Bunu yaparken izleyici için karakterin eylemi hâlâ anlaşılır ve inandırıcı kalmalıdır.'),
  ('Ezme ve uzatma (squash and stretch) uygulanırken top gibi bir nesnenin hangi özelliği korunmalıdır?', 'Hacim değişmez', ['Rengin sabit kalması gerekliliği', 'Hızın hep aynı kalması gerekliliği', 'Sesin hiç değişmemesi gerekliliği'], 'Nesne yassılırken yanlara, uzarken inceleşerek hacmini korumalıdır. Aksi hâlde nesne şişiyor ya da küçülüyor gibi görünür.'),
  ('Dudak eşleştirmede M, B ve P sesleri için ağız şekli nasıl çizilmelidir?', 'Kapalı dudak', ['Geniş açık ağız', 'Dişleri gösteren gülümseme', 'Yuvarlak dudak'], 'M, B ve P sesleri dudakların kapanmasını gerektirir. Bu sesler animasyonda kolayca tanınan ağız şekilleridir.'),
  ('Bir stop-motion yönetmeni tek bir saniyelik hareket için kuklanın kaç poz verildiğini ayarlarken genellikle neye göre karar verir?', 'Hareketin hızına göre', ['Havanın o günkü durumuna göre', 'Seslendirme sanatçısının yaşına göre', 'Film şeridinin rengine göre belirlenir'], 'Hızlı hareketlerde birerli, yavaş hareketlerde ikişerli çekim tercih edilir. Bu karar, akıcılık ve çalışma süresini birlikte belirler.'),
  ('Çizimli animasyonda \'gecikmeli hareket\' (drag) ilkesini en iyi hangi örnek gösterir?', 'Giysinin gövdeden geç tepki vermesi', ['Karakterin hiç hareket etmemesi ve donması', 'Işığın ters yöne gidip sönmesi', 'Sesin görüntüden önce gelmesi ve senkron kayması'], 'Drag, ağırlığı olan parçaların atalet nedeniyle ana harekete geç tepki vermesidir. Devam hareketi ilkesinin bir parçasıdır.'),
  ('Bilgisayarlı animasyonda \'kontrol noktası\' (key) ve \'enterpolasyon\' arasındaki ilişki nedir?', 'Anahtarı animatör, arayı bilgisayar verir', ['Animatör her kareyi elle çizer ve boyar', 'Bilgisayar anahtarları kendi seçip uygular', 'İkisi de hiç kullanılmaz ve el yordamı çalışılır'], 'Keyframe sisteminde animatör kritik pozları belirler. Yazılım aradaki değerleri hesaplayarak hareketi tamamlar.'),
  ('Pixar\'ın \'Luxo Jr.\' (1986) filminde lambaya kişilik kazandıran asıl animasyon yaklaşımı neydi?', 'Hareket ve duruşla duygu aktarmak', ['Lambaya ağız ve ses ekleyip konuşturmak', 'Gerçek lambaları çekip ses eklemek', 'Tümüyle elle çizim kullanıp renk vermek'], 'Lambaların yüzü ve sesi yoktur; duygu, eğilme ve zıplama gibi hareketlerle aktarılır. Bu yaklaşım Pixar\'ın temel felsefesini yansıtır.'),
  ('Bir animatör çekimin ortasında ağırlık duygusunu artırmak için hangi uygulamayı yapabilir?', 'Yere basarken kısa çökme eklemek', ['Hareketi hızlandırıp çizim sayısını azaltmak', 'Sesi artırıp efekt eklemek', 'Karakteri sürekli havada tutup yer çekimini kaldırmak'], 'Ağırlık, hareketin başlangıcında ve sonunda yavaşlık ve çökmeyle belirtilir. Böylece karakterin kütlesi hissedilir.'),
  ('Film döneminde kurgucuların orijinal negatifi korumak için üzerinde çalıştıkları pozitif kopyaya ne ad verilir?', 'Çalışma kopyası', ['Cevap baskısı, laboratuvarın ilk zamanlanmış kopyası', 'Ara negatif, orijinal negatiften çıkarılan kopya', 'Dağıtım kopyası, salonlara gönderilen baskı'], 'Kurgucular, değerli orijinal negatifi hasardan korumak için pozitif kopyayı keser ve yapıştırır. Kurgu bittiğinde negatif bu kopyaya göre kesilir.'),
  ('Linwood Dunn\'ın geliştirdiği ve Hollywood stüdyolarında yaygın kullanılan, çoklu film elementlerini tek şeride kopyalayan aygıt hangisidir?', 'Acme-Dunn optik baskı makinesi', ['Mitchell BNC stüdyo kamerası', 'Moviola dik kurgu makinesi', 'Technicolor üç şeritli kamera'], 'Dunn, optik baskı makinesini geliştirip sinemada efekt çalışmalarının temel aygıtı yaptı. Kompozisyon ve geçişler bu makineyle hazırlandı.'),
];
